168	    /** Whether a claim is overdue on the sheet's today: it is open (or pending), not deferred on it,
169	     *  and its {@link #lateFrom} is before it. */
170	    public boolean overdue(String sheetId, Person person, Claim claim) {
171	        Basis basis = now(sheetId);
172	        LocalDate today = basis.today();
173	        return claim.getStatus().isOpen() && !claim.isDeferredOn(today) && lateFrom(basis, person, claim).isBefore(today);
174	    }
