176	    /** The late charge on a claim taken as open (or pending) or not, overdue on the sheet's today (its {@link #lateFrom}
177	     *  before today; a correction has none): for each full 30 days it is overdue, the late percent in force on
178	     *  that boundary (its late-from plus 30, 60, 90 ... days) of its figure plus the charges of the boundaries
179	     *  before it (the charge compounds), rounded to two decimals by the claim's
180	     *  {@link #rounding}, the charges added up (a boundary whose percent is 0.00 adds nothing); 0.00 when it is not overdue. */
181	    private BigDecimal lateCharge(Basis basis, Person person, Claim claim, BigDecimal figure, boolean open) {
182	        BigDecimal none = BigDecimal.ZERO.setScale(2);
183	        LocalDate today = basis.today();
184	        if (!open || claim.isCorrection() || claim.isDeferredOn(today)) {
185	            return none;
186	        }
187	        LocalDate lateFrom = lateFrom(basis, person, claim);
188	        long periods = ChronoUnit.DAYS.between(lateFrom, today) / 30;
189	        if (periods <= 0) {
190	            return none;
191	        }
192	        RoundingMode rounding = rounding(basis, claim);
193	        BigDecimal charge = none;
194	        for (long n = 1; n <= periods; n++) {
195	            BigDecimal pct = basis.latePct(lateFrom.plusDays(30 * n));
196	            if (pct.signum() != 0) {
197	                charge = charge.add(figure.add(charge).multiply(pct).movePointLeft(2).setScale(2, rounding));
198	            }
199	        }
200	        return charge;
201	    }
