203	    /** Whether a claim of the person counts in the live totals on the sheet's today: it counts, it is
204	     *  not deferred on that day, and it is not an open (or pending) claim, unbound by a statement,
205	     *  dated within one of the person's holds or of a person retired on that day. */
206	    public static boolean countsLive(Person person, Claim claim, LocalDate today) {
207	        return claim.getStatus().counts() && !claim.isDeferredOn(today) && !leftOut(person, claim, today);
208	    }
