210	    /** Whether a claim of the person counts in a period's totals: by the status it had at the end of
211	     *  the period's last day (see Claim#statusOn) it counts, and the live rules do not leave it out:
212	     *  it is not deferred on the sheet's today, and it is not a claim open (or pending) now,
213	     *  unbound by a statement, dated within one of the person's holds or of a person retired on the
214	     *  sheet's today. */
215	    public static boolean countsAsOf(Person person, Claim claim, LocalDate end, LocalDate today) {
216	        ClaimStatus then = claim.statusOn(end);
217	        return then != null && then.counts() && !claim.isDeferredOn(today) && !leftOut(person, claim, today);
218	    }
219	
220	    /** Whether the live rules leave a claim of the person out: it is open (or pending) now, unbound
221	     *  by a statement, and dated within one of the person's holds or the person is retired on the
222	     *  sheet's today. */
223	    private static boolean leftOut(Person person, Claim claim, LocalDate today) {
224	        return claim.getStatus().isOpen() && !claim.isStated()
225	                && (person.isHeldOn(claim.getDate()) || person.isRetiredOn(today));
226	    }
