228	    /** The claims of a person that count in the live totals on the sheet's today. */
229	    public static List<Claim> live(Person person, List<Claim> theirs, LocalDate today) {
230	        return theirs.stream().filter(c -> countsLive(person, c, today)).toList();
231	    }
