240	    /** A person's due-total on a basis (see {@link #dueTotal(String, Person, List)}). */
241	    public BigDecimal dueTotal(Basis basis, Person person, List<Claim> theirs) {
242	        List<BigDecimal> figures = theirs.stream().filter(c -> c.getStatus().counts())
243	                .map(c -> figure(basis, person, c)).filter(d -> d != null).toList();
244	        LocalDate today = basis.today();
245	        boolean rated = RateRepository.inForce(basis.rates(person.gradeOn(today)), today).isPresent();
246	        if (!rated && figures.isEmpty()) {
247	            return null;
248	        }
249	        BigDecimal sum = figures.stream().reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
250	        BigDecimal cap = basis.cap();
251	        return cap == null ? sum : sum.min(cap);
252	    }
