254	    /** A claim's live due at the rate, in force on the claim's date, for the person's grade in force
255	     *  on that date: amount
256	     *  times pct divided by 100, rounded to two decimals by the claim's {@link #rounding} (the floor is
257	     *  applied later, see {@link #floored}); null when no rate applies on that date. */
258	    private BigDecimal due(Basis basis, Person person, Claim claim) {
259	        RoundingMode rounding = rounding(basis, claim);
260	        return RateRepository.inForce(basis.rates(person.gradeOn(claim.getDate())), claim.getDate())
261	                .map(Rate::getPct)
262	                .map(pct -> claim.getAmount().multiply(pct).movePointLeft(2).setScale(2, rounding))
263	                .orElse(null);
264	    }
