266	    /** How a claim's live figures round: half up when the date it rounds by (a correction's is that of
267	     *  the claim it corrects) is before the sheet's policy date, else half to even. */
268	    private RoundingMode rounding(Basis basis, Claim claim) {
269	        return claim.roundsBy().isBefore(basis.policyDateInForce()) ? RoundingMode.HALF_UP
270	                : RoundingMode.HALF_EVEN;
271	    }
