275	/** Where a claim is in its life: it starts as a draft, is opened and then settled; a clerk's settle
276	 *  above the clerk limit leaves it pending until a steward approves it (settled) or rejects it (open
277	 *  again); a draft, open or pending claim may be voided, and a steward may void a settled claim
278	 *  within days of its settlement (see {@code ClaimService}). A voided claim cannot change status. */
279	public enum ClaimStatus {
280	    DRAFT, OPEN, PENDING, SETTLED, VOID;
281	
282	    /** Whether a claim at this status may move to {@code to}: a pending claim moves to settled or
283	     *  back to open only by approval or rejection, which ask for it by {@link #PENDING} itself. */
284	    public boolean canBecome(ClaimStatus to) {
285	        return switch (to) {
286	            case OPEN -> this == DRAFT;
287	            case SETTLED, PENDING -> this == OPEN;
288	            case VOID -> this == DRAFT || isOpen();
289	            case DRAFT -> false;
290	        };
291	    }
292	
293	    /** Whether a claim at this status is open: open, or pending approval of its settle. */
294	    public boolean isOpen() {
295	        return this == OPEN || this == PENDING;
296	    }
297	
298	    /** Whether a claim at this status counts toward what its person has claimed. */
299	    public boolean counts() {
300	        return isOpen() || this == SETTLED;
301	    }
302	}
