55	        this.sheetTags = sheetTags;
56	        this.voidReasons = voidReasons;
57	        this.audit = audit;
58	    }
59	
60	    /** The claims on the sheet, newest first. */
61	    @Transactional(readOnly = true)
62	    public List<Claim> list(String sheetId) {
63	        return claims.findBySheetIdOrderByListedDesc(sheetId);
64	    }
65	
66	    /** Add a claim for a person; a date left out takes the sheet's entry date, or its today when none
67	     *  is set. Refused when the due-by it
68	     *  would be fixed with falls inside a closed period, or after the person's retirement day, and when a correction (a negative
69	     *  amount) does not name a settled claim of the person. */
70	    @Transactional
71	    public Claim add(String sheetId, String user, long personId, BigDecimal amount, LocalDate date, String note) {
72	        return add(sheetId, user, personId, amount, date, note, null);
73	    }
74	
75	    /** Add a claim for a person, naming the number of the claim it corrects (only a correction keeps it). */
76	    @Transactional
77	    public Claim add(String sheetId, String user, long personId, BigDecimal amount, LocalDate date, String note,
78	            String corrects) {
79	        return add(sheetId, user, personId, amount, date, note, corrects, null);
80	    }
81	
82	    /** Add a claim for a person with an external reference (null: none); refused as well when another
83	     *  claim of the sheet has the reference, comparing without regard to case. */
84	    @Transactional
85	    public Claim add(String sheetId, String user, long personId, BigDecimal amount, LocalDate date, String note,
86	            String corrects, String ref) {
87	        return add(sheetId, user, personId, amount, date, note, corrects, ref, null);
88	    }
89	
90	    /** Add a claim for a person with tags (as {@link Tags} stores them; null: none). */
91	    @Transactional
92	    public Claim add(String sheetId, String user, long personId, BigDecimal amount, LocalDate date, String note,
93	            String corrects, String ref, String tags) {
94	        refuseRefUsed(sheetId, ref, null);
95	        LocalDate on = date != null ? date : sheets.entryDay(sheetId);
96	        int terms = terms(sheetId, person(sheetId, personId), on);
97	        LocalDate dueBy = holidays.businessDaysAfter(sheetId, on, terms);
98	        refuseClosed(sheetId, dueBy);
99	        refuseRetired(person(sheetId, personId), on);
100	        Claim corrected = corrected(sheetId, personId, amount, corrects);
101	        return rollup.tracking(sheetId, user, () -> {
102	            Person person = person(sheetId, personId);
103	            Claim draft = new Claim(sheetId, personId, amount, on, note,
104	                    corrected == null ? null : corrected.getNumber(), corrected == null ? null : corrected.getDate(),
105	                    dueBy);
106	            draft.setTerms(terms);
107	            draft.setRef(ref);
108	            draft.setTags(tags);
109	            boolean late = periods.softClosedOn(sheetId, dueBy);
110	            if (late) {
111	                draft.markLateEntry();
112	            }
113	            logStatus(sheetId, user, person, draft);
114	            Claim claim = claims.saveAndFlush(draft);
115	            audit.recordOnCommit(record("CLAIM_ADDED", sheetId, user, person, claim)
116	                    + (ref != null ? " ref=" + ref : "") + (tags != null ? " tags=" + tags : ""));
117	            keepTags(sheetId, tags);
118	            if (late) {
119	                audit.recordOnCommit(record("LATE_ENTRY", sheetId, user, person, claim));
120	            }
121	            return claim;
122	        });
123	    }
124	
125	    /** Change a draft claim's amount, date, note and external reference (null: none); a date left out
126	     *  takes the sheet's today. Refused when another claim of the sheet has the reference, and
127	     *  when the claim is not a draft (an open claim is changed by voiding it and adding a new one), and
128	     *  when the claim's due-by (which the edit leaves) falls inside a closed period, and when the new
129	     *  date is after the person's retirement day. */
130	    @Transactional
131	    public Claim edit(String sheetId, String user, long claimId, BigDecimal amount, LocalDate date, String note,
132	            String corrects, String ref, String tags) {
133	        Claim claim = lock(sheetId, claimId);
134	        if (claim.getStatus() != ClaimStatus.DRAFT || claim.editLockedFor(user)) {
135	            throw new ResponseStatusException(HttpStatus.CONFLICT,
136	                    "A " + claim.getStatus() + " claim cannot be edited, nor one another user is editing");
137	        }
138	        refuseRefUsed(sheetId, ref, claim.getId());
139	        LocalDate on = date != null ? date : sheets.today(sheetId);
140	        refuseClosed(sheetId, claim.getDueBy());
141	        refuseRetired(person(sheetId, claim.getPersonId()), on);
142	        Claim corrected = corrected(sheetId, claim.getPersonId(), amount, corrects);
143	        return rollup.tracking(sheetId, user, () -> {
144	            claim.setAmount(amount);
145	            claim.setCorrects(corrected == null ? null : corrected.getNumber());
146	            claim.setCorrectedDate(corrected == null ? null : corrected.getDate());
147	            claim.setDate(on);
148	            claim.setNote(note);
149	            claim.setRef(ref);
150	            claim.setTags(tags);
151	            claim.setEditLockedBy(null);
152	            claim.setEditedBy(user);
153	            keepTags(sheetId, tags);
154	            Claim saved = claims.saveAndFlush(claim);
155	            audit.recordOnCommit(record("CLAIM_EDITED", sheetId, user, person(sheetId, saved.getPersonId()), saved));
156	            return saved;
157	        });
158	    }
159	
160	    /** Change only a draft claim's amount (the row's inline entry), keeping its date, note and the
161	     *  number it corrects; refused exactly as {@link #edit} refuses, and recorded as it records. */
162	    @Transactional
163	    public Claim editAmount(String sheetId, String user, long claimId, BigDecimal amount) {
164	        Claim claim = lock(sheetId, claimId);
165	        return edit(sheetId, user, claimId, amount, claim.getDate(), claim.getNote(), claim.getCorrects(),
166	                claim.getRef(), claim.getTags());
167	    }
168	
169	    /** Open a claim's editor for the user, locking the claim for every other user until it is saved
170	     *  or cancelled or the sheet's today changes; an editor the user had open on another claim of the
171	     *  same person is closed. Refused when the claim is not a draft or another user has its editor
172	     *  open (409), and when its due-by falls inside a closed period (423). Records nothing. */
173	    @Transactional
174	    public Claim openEditor(String sheetId, String user, long claimId) {
175	        Claim claim = lock(sheetId, claimId);
176	        if (claim.getStatus() != ClaimStatus.DRAFT || claim.editLockedFor(user)) {
177	            throw new ResponseStatusException(HttpStatus.CONFLICT,
178	                    "A " + claim.getStatus() + " claim cannot be edited, nor one another user is editing");
179	        }
180	        refuseClosed(sheetId, claim.getDueBy());
181	        claims.releaseOtherEditLocks(sheetId, claim.getPersonId(), user, claim.getId());
182	        claim.setEditLockedBy(user);
183	        return claims.saveAndFlush(claim);
184	    }
185	
186	    /** Close the claim's editor the user has open (cancelled), unlocking the claim; a claim whose
187	     *  editor the user does not have open is left as it is. Records nothing. */
188	    @Transactional
189	    public Claim closeEditor(String sheetId, String user, long claimId) {
190	        Claim claim = lock(sheetId, claimId);
191	        if (!user.equals(claim.getEditLockedBy())) {
192	            return claim;
193	        }
194	        claim.setEditLockedBy(null);
195	        return claims.saveAndFlush(claim);
196	    }
197	
198	    /** Move a claim to a new status; a change its current status does not allow is refused, and so
199	     *  is settling a claim by the user who opened or last edited it, and any change to a claim whose due-by falls inside a
200	     *  closed period, and any change the permission matrix does not allow the user's role. A clerk settling a claim whose due is above the sheet's clerk limit leaves it pending
201	     *  a steward's approval instead; but settling a claim that needs a proof and has none is refused
202	     *  before the clerk limit is considered. */
203	    @Transactional
204	    public Claim changeStatus(String sheetId, String user, long claimId, ClaimStatus to) {
205	        return changeStatus(sheetId, user, claimId, to, null);
206	    }
207	
208	    /** Number the claims a bulk settle settled (or left pending) as the sheet's next settle batch;
209	     *  nothing when it settled none (0). Returns the batch's number. */
210	    @Transactional
211	    public int markSettleBatch(String sheetId, List<Long> claimIds) {
212	        if (claimIds.isEmpty()) {
213	            return 0;
214	        }
215	        int batch = sheets.nextSettleBatch(sheetId);
216	        for (Long claimId : claimIds) {
217	            Claim claim = lock(sheetId, claimId);
218	            claim.setSettleBatch(batch);
219	            claims.saveAndFlush(claim);
220	        }
221	        return batch;
222	    }
223	
224	    /** Void a claim as {@link #changeStatus} does; while the sheet has void reasons, the void needs
225	     *  one of them (refused without), kept on the claim and ending its record. */
226	    @Transactional
227	    public Claim voidClaim(String sheetId, String user, long claimId, String reason) {
228	        return changeStatus(sheetId, user, claimId, ClaimStatus.VOID, reason);
229	    }
230	
231	    private Claim changeStatus(String sheetId, String user, long claimId, ClaimStatus to, String reason) {
232	        Claim claim = lock(sheetId, claimId);
233	        refuseClosed(sheetId, claim.getDueBy());
234	        String voidReason = to == ClaimStatus.VOID ? voidReasons.required(sheetId, reason) : null;
235	        if (to == ClaimStatus.VOID && claim.getStatus() == ClaimStatus.SETTLED) {
236	            return voidSettled(sheetId, user, claim, voidReason);
237	        }
238	        if (!claim.getStatus().canBecome(to) || to == ClaimStatus.PENDING) {
239	            throw new ResponseStatusException(HttpStatus.CONFLICT,
240	                    "A " + claim.getStatus() + " claim cannot become " + to);
241	        }
242	        String action = switch (to) {
243	            case OPEN -> "open";
244	            case SETTLED -> "settle";
245	            default -> "void";
246	        };
247	        if (!roles.may(sheetId, user, action)) {
248	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Your role may not " + action + " a claim");
249	        }
250	        if (to == ClaimStatus.OPEN) {
251	            refuseUnnoted(sheetId, claim);
252	        }
253	        if (to == ClaimStatus.SETTLED && claim.isDeferredOn(sheets.today(sheetId))) {
254	            throw new ResponseStatusException(HttpStatus.CONFLICT,
255	                    "A claim deferred until " + claim.getDeferredUntil() + " cannot be settled before then");
256	        }
257	        if (to == ClaimStatus.SETTLED && claim.openedOrEditedBy(user)) {
258	            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
259	                    "The user who opened or last edited a claim cannot settle it");
260	        }
261	        if (to == ClaimStatus.SETTLED) {
262	            refuseUnproved(sheetId, claim);
263	        }
264	        ClaimStatus becomes = to == ClaimStatus.SETTLED && overClerkLimit(sheetId, user, claim)
265	                ? ClaimStatus.PENDING : to;
266	        return rollup.tracking(sheetId, user, () -> {
267	            Person person = person(sheetId, claim.getPersonId());
268	            if (becomes == ClaimStatus.SETTLED) {
269	                // Settling fixes the due at what it is now, while the claim is still open (the figure a
270	                // statement bound it to, if any, and its late charge); later changes to rates, the
271	                // late percent and the sheet's today do not alter it.
272	                claim.setSettledDue(dues.figure(sheetId, person, claim));
273	            }
274	            // A void claim keeps the number it had (never reused).
275	            claim.setStatus(becomes);
276	            if (becomes == ClaimStatus.VOID) {
277	                claim.setVoidReason(voidReason);
278	            }
279	            if (becomes == ClaimStatus.OPEN) {
280	                claim.setNumber(nextNumber(sheetId, claim.getDueBy()));
281	                claim.setOpenedBy(user);
282	            }
283	            logStatus(sheetId, user, person, claim);
284	            Claim saved = claims.saveAndFlush(claim);
285	            String event = switch (becomes) {
286	                case OPEN -> "CLAIM_OPENED";
287	                case PENDING -> "CLAIM_PENDING";
288	                case SETTLED -> "CLAIM_SETTLED";
289	                case VOID -> "CLAIM_VOIDED";
290	                case DRAFT -> throw new IllegalStateException("a claim never returns to DRAFT");
291	            };
292	            String line = record(event, sheetId, user, person, saved);
293	            if (becomes == ClaimStatus.SETTLED) {
294	                line += " due=" + dueText(saved.getSettledDue());
295	            }
296	            line += reasonText(voidReason);
297	            audit.recordOnCommit(line);
298	            if (becomes == ClaimStatus.SETTLED) {
299	                watches.notifyWatchers(sheetId, user, person, saved.getNumber());
300	            }
301	            return saved;
302	        });
303	    }
304	
305	    /** Void a settled claim: only a steward may, within {@value #VOID_SETTLED_DAYS} days of its
306	     *  settlement (the first SETTLED line of its status log) by the sheet's today. It keeps its
307	     *  number and settled due, which leaves every total; the record ends with the figure reversed. */
308	    private Claim voidSettled(String sheetId, String user, Claim claim, String voidReason) {
309	        if (!SheetRole.STEWARD.equals(roles.roleOf(sheetId, user))) {
310	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward can void a settled claim");
311	        }
312	        LocalDate today = sheets.today(sheetId);
313	        LocalDate settled = claim.getLog().stream().filter(l -> l.getStatus() == ClaimStatus.SETTLED)
314	                .map(ClaimLog::getOn).findFirst().orElse(null);
315	        if (settled == null || today.isBefore(settled) || today.isAfter(settled.plusDays(VOID_SETTLED_DAYS))) {
316	            throw new ResponseStatusException(HttpStatus.CONFLICT,
317	                    "A settled claim can only be voided within " + VOID_SETTLED_DAYS + " days of its settlement");
318	        }
319	        return rollup.tracking(sheetId, user, () -> {
320	            Person person = person(sheetId, claim.getPersonId());
321	            BigDecimal reversed = dues.figure(sheetId, person, claim);
322	            claim.setStatus(ClaimStatus.VOID);
323	            claim.setVoidReason(voidReason);
324	            logStatus(sheetId, user, person, claim);
325	            Claim saved = claims.saveAndFlush(claim);
326	            audit.recordOnCommit(record("CLAIM_VOIDED", sheetId, user, person, saved) + " reversed=" + dueText(reversed)
327	                    + reasonText(voidReason));
328	            return saved;
329	        });
330	    }
331	
332	    /** Defer an open claim until a day after the sheet's today: until the sheet's today reaches it,
333	     *  the claim counts in no total, is not overdue, cannot be settled and a statement leaves it
334	     *  unbound. Refused when the claim's period is closed, the claim is not open, or the day is not
335	     *  after the sheet's today. */
336	    @Transactional
337	    public Claim defer(String sheetId, String user, long claimId, LocalDate until) {
338	        Claim claim = lock(sheetId, claimId);
339	        refuseClosed(sheetId, claim.getDueBy());
340	        if (claim.getStatus() != ClaimStatus.OPEN) {
341	            throw new ResponseStatusException(HttpStatus.CONFLICT,
342	                    "A " + claim.getStatus() + " claim cannot be deferred");
343	        }
344	        if (!until.isAfter(sheets.today(sheetId))) {
345	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
346	                    "A claim can only be deferred to a date after the sheet's today");
347	        }
348	        return rollup.tracking(sheetId, user, () -> {
349	            Person person = person(sheetId, claim.getPersonId());
350	            claim.deferUntil(until);
351	            Claim saved = claims.saveAndFlush(claim);
352	            audit.recordOnCommit(record("CLAIM_DEFERRED", sheetId, user, person, saved) + " until=" + until);
353	            return saved;
354	        });
355	    }
356	
357	    /** Raise a claim's proofs count by one. Refused when the claim is settled or void, or its period
358	     *  is closed. It changes no figure. */
359	    @Transactional
360	    public Claim addProof(String sheetId, String user, long claimId) {
361	        Claim claim = lock(sheetId, claimId);
362	        refuseClosed(sheetId, claim.getDueBy());
363	        if (claim.getStatus() == ClaimStatus.SETTLED || claim.getStatus() == ClaimStatus.VOID) {
364	            throw new ResponseStatusException(HttpStatus.CONFLICT,
365	                    "A " + claim.getStatus() + " claim cannot be given a proof");
366	        }
367	        Person person = person(sheetId, claim.getPersonId());
368	        claim.addProof();
369	        Claim saved = claims.saveAndFlush(claim);
370	        audit.recordOnCommit(record("CLAIM_PROOF_ADDED", sheetId, user, person, saved) + " proofs=" + saved.getProofs());
371	        return saved;
372	    }
373	
374	    /** Remind an open or pending claim: it is reminded on the sheet's today. Refused when the claim
375	     *  is in any other status, and when it was already reminded on the sheet's today. It changes no
376	     *  figure. */
377	    @Transactional
378	    public Claim remind(String sheetId, String user, long claimId) {
379	        Claim claim = lock(sheetId, claimId);
380	        if (claim.getStatus() != ClaimStatus.OPEN && claim.getStatus() != ClaimStatus.PENDING) {
381	            throw new ResponseStatusException(HttpStatus.CONFLICT,
382	                    "A " + claim.getStatus() + " claim cannot be reminded");
383	        }
384	        LocalDate today = sheets.today(sheetId);
385	        if (today.equals(claim.getRemindedOn())) {
386	            throw new ResponseStatusException(HttpStatus.TOO_MANY_REQUESTS,
387	                    "The claim was already reminded today");
388	        }
389	        Person person = person(sheetId, claim.getPersonId());
390	        claim.remindOn(today);
391	        Claim saved = claims.saveAndFlush(claim);
392	        audit.recordOnCommit(record("REMIND", sheetId, user, person, saved));
393	        return saved;
394	    }
395	
396	    /** Comment a claim, in any status: the comment is kept with the user and the sheet's today. Refused
397	     *  when the text is empty. It changes no figure. */
398	    @Transactional
399	    public Claim comment(String sheetId, String user, long claimId, String text) {
400	        String trimmed = text == null ? "" : text.trim();
401	        if (trimmed.isEmpty()) {
402	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "A comment cannot be empty");
403	        }
404	        Claim claim = lock(sheetId, claimId);
405	        Person person = person(sheetId, claim.getPersonId());
406	        claim.comment(user, sheets.today(sheetId), trimmed);
407	        Claim saved = claims.saveAndFlush(claim);
408	        audit.recordOnCommit(record("COMMENT_ADDED", sheetId, user, person, saved) + " text=" + trimmed);
409	        return saved;
410	    }
411	
412	    /** Approve a pending claim: it becomes settled, its due fixed at the figure it has now (its live
413	     *  figure and late charge). Refused unless the claim is pending, the user is a steward and is not
414	     *  the one who opened or last edited it, the claim's period is open, and it has a proof if it needs one. */
415	    @Transactional
416	    public Claim approve(String sheetId, String user, long claimId) {
417	        Claim claim = lockPending(sheetId, user, claimId);
418	        if (claim.openedOrEditedBy(user)) {
419	            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
420	                    "The user who opened or last edited a claim cannot approve it");
421	        }
422	        refuseUnproved(sheetId, claim);
423	        return rollup.tracking(sheetId, user, () -> {
424	            Person person = person(sheetId, claim.getPersonId());
425	            claim.setSettledDue(dues.figure(sheetId, person, claim));
426	            claim.setStatus(ClaimStatus.SETTLED);
427	            logStatus(sheetId, user, person, claim);
428	            Claim saved = claims.saveAndFlush(claim);
429	            audit.recordOnCommit(record("CLAIM_APPROVED", sheetId, user, person, saved)
430	                    + " due=" + dueText(saved.getSettledDue()));
431	            watches.notifyWatchers(sheetId, user, person, saved.getNumber());
432	            return saved;
433	        });
434	    }
435	
436	    /** Re-settle a settled claim: its due is fixed again at the figure it would have today as an open
437	     *  claim bound by no statement (today's rates, grades, floor and late charge). Refused unless the
438	     *  claim is settled, the user is a steward, and the claim's period is open. */
439	    @Transactional
440	    public Claim resettle(String sheetId, String user, long claimId) {
441	        Claim claim = lock(sheetId, claimId);
442	        refuseClosed(sheetId, claim.getDueBy());
443	        if (claim.getStatus() != ClaimStatus.SETTLED) {
444	            throw new ResponseStatusException(HttpStatus.CONFLICT, "Only a SETTLED claim can be re-settled");
445	        }
446	        if (!SheetRole.STEWARD.equals(roles.roleOf(sheetId, user))) {
447	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward can re-settle a claim");
448	        }
449	        return rollup.tracking(sheetId, user, () -> {
450	            Person person = person(sheetId, claim.getPersonId());
451	            BigDecimal old = dues.figure(sheetId, person, claim);
452	            BigDecimal now = dues.openFigure(sheetId, person, claim);
453	            claim.setSettledDue(now);
454	            claim.logStatus(user, sheets.today(sheetId), now);
455	            Claim saved = claims.saveAndFlush(claim);
456	            audit.recordOnCommit(record("CLAIM_RESETTLED", sheetId, user, person, saved)
457	                    + " old=" + dueText(old) + " new=" + dueText(now));
458	            watches.notifyWatchers(sheetId, user, person, saved.getNumber());
459	            return saved;
460	        });
461	    }
462	
463	    /** Reject a pending claim for a reason: it is open again, bound again by its person's last
464	     *  statement if that statement included it. Refused unless the claim is pending, the user is a
465	     *  steward, and the claim's period is open. */
466	    @Transactional
467	    public Claim reject(String sheetId, String user, long claimId, String reason) {
468	        Claim claim = lockPending(sheetId, user, claimId);
469	        return rollup.tracking(sheetId, user, () -> {
470	            Person person = person(sheetId, claim.getPersonId());
471	            claim.setStatus(ClaimStatus.OPEN);
472	            // back to open, it is no longer settled by the batch that left it pending
473	            claim.setSettleBatch(null);
474	            logStatus(sheetId, user, person, claim);
475	            Claim saved = claims.saveAndFlush(claim);
476	            audit.recordOnCommit(record("CLAIM_REJECTED", sheetId, user, person, saved) + " reason=" + reason);
477	            return saved;
478	        });
479	    }
480	
481	    /** Move a draft, open or pending claim to another person on the sheet. It keeps its number, date
482	     *  and status, loses any figure a statement bound it to, and is listed as its new person's newest
483	     *  claim. Refused unless the permission matrix allows the user's role to reassign, and when the claim is settled or void, the person
484	     *  is the one it is already for, the claim's period is closed, or the claim is dated after the
485	     *  new person's retirement day. */
486	    @Transactional
487	    public Claim reassign(String sheetId, String user, long claimId, long toPersonId) {
488	        return reassign(sheetId, user, claimId, toPersonId, false);
489	    }
490	
491	    /** Move a claim as {@link #reassign(String, String, long, long)} does; a bulk move ({@code
492	     *  inBulk}) also takes a claim that is already the person's, listing it as their newest. */
493	    @Transactional
494	    public Claim reassign(String sheetId, String user, long claimId, long toPersonId, boolean inBulk) {
495	        Claim claim = lock(sheetId, claimId);
496	        if (!roles.may(sheetId, user, "reassign")) {
497	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Your role may not reassign a claim");
498	        }
499	        if (claim.getStatus() == ClaimStatus.SETTLED || claim.getStatus() == ClaimStatus.VOID) {
500	            throw new ResponseStatusException(HttpStatus.CONFLICT,
501	                    "A " + claim.getStatus() + " claim cannot be reassigned");
502	        }
503	        if (!inBulk && claim.getPersonId() == toPersonId) {
504	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "The claim is already that person's");
505	        }
506	        refuseClosed(sheetId, claim.getDueBy());
507	        Person from = person(sheetId, claim.getPersonId());
508	        Person to = person(sheetId, toPersonId);
509	        refuseRetired(to, claim.getDate());
510	        return rollup.tracking(sheetId, user, () -> {
511	            claim.moveTo(to.getId(), claims.nextListed());
512	            Claim saved = claims.saveAndFlush(claim);
513	            audit.recordOnCommit(record("CLAIM_REASSIGNED", sheetId, user, to, saved)
514	                    + " from=" + from.getName() + " to=" + to.getName());
515	            return saved;
516	        });
517	    }
518	
519	    /** Re-date an open or pending claim: it keeps the due-by it was fixed with, and so its period and
520	     *  number, and any figure a statement bound it to. Refused unless the user is a steward, and when
521	     *  the claim is not open or pending, its period is closed, or the new date is after the person's
522	     *  retirement day. */
523	    @Transactional
524	    public Claim redate(String sheetId, String user, long claimId, LocalDate date) {
525	        Claim claim = lock(sheetId, claimId);
526	        if (!SheetRole.STEWARD.equals(roles.roleOf(sheetId, user))) {
527	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward can re-date a claim");
528	        }
529	        if (claim.getStatus() != ClaimStatus.OPEN && claim.getStatus() != ClaimStatus.PENDING) {
530	            throw new ResponseStatusException(HttpStatus.CONFLICT,
531	                    "A " + claim.getStatus() + " claim cannot be re-dated");
532	        }
533	        refuseClosed(sheetId, claim.getDueBy());
534	        refuseRetired(person(sheetId, claim.getPersonId()), date);
535	        LocalDate old = claim.getDate();
536	        return rollup.tracking(sheetId, user, () -> {
537	            Person person = person(sheetId, claim.getPersonId());
538	            claim.setDate(date);
539	            Claim saved = claims.saveAndFlush(claim);
540	            audit.recordOnCommit(record("CLAIM_REDATED", sheetId, user, person, saved)
541	                    + " old=" + old + " new=" + date);
542	            return saved;
543	        });
544	    }
545	
546	    /** What a split leaves:the original claim, with the rest of its amount, and the new open claim
547	     *  split off it. */
548	    public record Split(Claim original, Claim split) {
549	    }
550	
551	    /** Split an amount (above 0.00 and below the claim's amount) off an open claim: it keeps the rest
552	     *  of its amount and loses any figure a statement bound it to, and a new open claim of the amount,
553	     *  the same date and note, the next number, opened by the user and due by the terms in force on
554	     *  the date, is listed as its person's newest claim. Refused when the claim is not open (or is
555	     *  deferred), its period is closed, the amount is out of range, or the permission matrix does not
556	     *  allow the user's role to open a claim. */
557	    @Transactional
558	    public Split split(String sheetId, String user, long claimId, BigDecimal part) {
559	        Claim claim = lock(sheetId, claimId);
560	        refuseClosed(sheetId, claim.getDueBy());
561	        if (claim.getStatus() != ClaimStatus.OPEN || claim.isDeferredOn(sheets.today(sheetId))) {
562	            throw new ResponseStatusException(HttpStatus.CONFLICT, "Only an open claim that is not deferred can be split");
563	        }
564	        if (!roles.may(sheetId, user, "open")) {
565	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Your role may not open a claim");
566	        }
567	        if (part.signum() <= 0 || part.compareTo(claim.getAmount()) >= 0) {
568	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
569	                    "The amount split off must be above 0.00 and below the claim's amount");
570	        }
571	        return rollup.tracking(sheetId, user, () -> {
572	            Person person = person(sheetId, claim.getPersonId());
573	            int terms = terms(sheetId, person, claim.getDate());
574	            LocalDate dueBy = holidays.businessDaysAfter(sheetId, claim.getDate(), terms);
575	            Claim draft = claim.splitOff(part, nextNumber(sheetId, dueBy), user, dueBy, terms);
576	            logStatus(sheetId, user, person, draft);
577	            Claim original = claims.saveAndFlush(claim);
578	            Claim split = claims.saveAndFlush(draft);
579	            audit.recordOnCommit(record("CLAIM_SPLIT", sheetId, user, person, original) + " into=" + split.getNumber());
580	            audit.recordOnCommit(record("CLAIM_OPENED", sheetId, user, person, split));
581	            return new Split(original, split);
582	        });
583	    }
584	
585	    /** The pending claim a steward approves or rejects, locked; refused when it is not pending, the
586	     *  user is not a steward, or its period is closed. */
587	    private Claim lockPending(String sheetId, String user, long claimId) {
588	        Claim claim = lock(sheetId, claimId);
589	        refuseClosed(sheetId, claim.getDueBy());
590	        if (claim.getStatus() != ClaimStatus.PENDING) {
591	            throw new ResponseStatusException(HttpStatus.CONFLICT,
592	                    "Only a PENDING claim can be approved or rejected");
593	        }
594	        if (!SheetRole.STEWARD.equals(roles.roleOf(sheetId, user))) {
595	            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
596	                    "Only a steward can approve or reject a claim");
597	        }
598	        return claim;
599	    }
600	
601	    /** Log the status the claim has now, changed by the user on the sheet's today, with its due as
602	     *  computed at this moment. */
603	    private void logStatus(String sheetId, String user, Person person, Claim claim) {
604	        claim.logStatus(user, sheets.today(sheetId), dues.figure(sheetId, person, claim));
605	    }
606	
607	    private Claim lock(String sheetId, long claimId) {
608	        return claims.lockByIdAndSheetId(claimId, sheetId)
609	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet"));
610	    }
611	
612	    private static String dueText(BigDecimal due) {
613	        return due == null ? "n/a" : due.setScale(2).toPlainString();
614	    }
615	
616	    /** The number for a claim due by the day opened now: under period numbering, the next in its period
617	     *  (<period name>-<n>), or for one in no period the next X-<n>; otherwise the next on the sheet. */
618	    private String nextNumber(String sheetId, LocalDate dueBy) {
619	        if (!sheets.periodNumbering(sheetId)) {
620	            return String.valueOf(sheets.nextClaimNumber(sheetId));
621	        }
622	        return periods.findOn(sheetId, dueBy)
623	                .map(p -> {
624	                    periods.advanceClaimNumber(p.getId());
625	                    return p.getName() + "-" + periods.lastClaimNumber(p.getId());
626	                })
627	                .orElseGet(() -> "X-" + sheets.nextUnperiodNumber(sheetId));
628	    }
629	
630	    /** The claim a claim of the amount corrects: none for an amount of 0.00 or more; for a correction
631	     *  (a negative amount), the one of the number given, which must be a settled claim of the person,
632	     *  or else it is refused. */
633	    private Claim corrected(String sheetId, long personId, BigDecimal amount, String corrects) {
634	        if (amount.signum() >= 0) {
635	            return null;
636	        }
637	        return (corrects == null ? Optional.<Claim>empty()
638	                : claims.findBySheetIdAndPersonIdAndNumberAndStatus(sheetId, personId, corrects, ClaimStatus.SETTLED))
639	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.BAD_REQUEST,
640	                        "A negative amount must correct a settled claim of the same person"));
641	    }
642	
643	    /** Refuse a change to a claim due by the day when the day falls inside a closed period. */
644	    private void refuseClosed(String sheetId, LocalDate day) {
645	        if (periods.closedOn(sheetId, day)) {
646	            throw new ResponseStatusException(HttpStatus.LOCKED, "That claim's period is closed");
647	        }
648	    }
649	
650	    /** Whether a clerk is settling a claim whose due is above the sheet's clerk limit in force on its today; a claim with
651	     *  no due (n/a) is within any limit, and a steward settles anything. */
652	    private boolean overClerkLimit(String sheetId, String user, Claim claim) {
653	        BigDecimal limit = sheets.clerkLimit(sheetId);
654	        if (limit == null || SheetRole.STEWARD.equals(roles.roleOf(sheetId, user))) {
655	            return false;
656	        }
657	        BigDecimal due = dues.figure(sheetId, person(sheetId, claim.getPersonId()), claim);
658	        return due != null && due.compareTo(limit) > 0;
659	    }
660	
661	    /** Refuse settling or approving a claim with no proofs whose due is above the proof threshold in
662	     *  force on the claim's date: its person's grade's (on that date) when one is set, or else the
663	     *  sheet's; a claim with no due (n/a) and a claim with no threshold need none. */
664	    private void refuseUnproved(String sheetId, Claim claim) {
665	        if (claim.getProofs() > 0) {
666	            return;
667	        }
668	        Person person = person(sheetId, claim.getPersonId());
669	        BigDecimal threshold = sheets.proofThresholdFor(sheetId, person.gradeOn(claim.getDate()), claim.getDate());
670	        if (threshold == null) {
671	            return;
672	        }
673	        BigDecimal due = dues.figure(sheetId, person, claim);
674	        if (due != null && due.compareTo(threshold) > 0) {
675	            throw new ResponseStatusException(HttpStatus.PRECONDITION_REQUIRED,
676	                    "A claim whose due is above the proof threshold needs a proof first");
677	        }
678	    }
679	
680	    /** Refuse opening a claim with an empty note whose due is above the sheet's note threshold in
681	     *  force on the claim's date; a claim with no due (n/a) and a sheet with no threshold need none. */
682	    private void refuseUnnoted(String sheetId, Claim claim) {
683	        BigDecimal threshold = sheets.noteThreshold(sheetId, claim.getDate());
684	        if (threshold == null || (claim.getNote() != null && !claim.getNote().isBlank())) {
685	            return;
686	        }
687	        BigDecimal due = dues.figure(sheetId, person(sheetId, claim.getPersonId()), claim);
688	        if (due != null && due.compareTo(threshold) > 0) {
689	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
690	                    "A claim whose due is above the note threshold needs a note before it is opened");
691	        }
692	    }
693	
694	    /** Refuse a claim of the person dated after the day they are retired from. */
695	    private static void refuseRetired(Person person, LocalDate day) {
696	        if (person.getRetiredFrom() != null && day.isAfter(person.getRetiredFrom())) {
697	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
698	                    "A claim cannot be dated after the person's retirement");
699	        }
700	    }
701	
702	    /** The terms a claim of the person dated on the day has its due-by fixed with (the terms-th
703	     *  business day after its date, skipping every Saturday, Sunday and holiday of the sheet): the
704	     *  first of the person's own terms, their grade's and the sheet's, each as in force on the day. */
705	    private int terms(String sheetId, Person person, LocalDate on) {
706	        Integer own = person.getTerms();
707	        return own != null ? own : sheets.termsFor(sheetId, person.gradeOn(on), on);
708	    }
709	
710	    /** Refuse a reference (null: none) another claim of the sheet than the one given (null: any) has,
711	     *  comparing without regard to case. */
712	    /** The tags ever used on the sheet, in order. */
713	    @Transactional(readOnly = true)
714	    public List<String> tags(String sheetId) {
715	        return sheetTags.findBySheetIdOrderByTagAsc(sheetId).stream().map(SheetTag::getTag).toList();
716	    }
717	
718	    /** Keep each of the tags (as {@link Tags} stores them) as used on the sheet. */
719	    private void keepTags(String sheetId, String tags) {
720	        for (String tag : Tags.of(tags)) {
721	            if (!sheetTags.existsBySheetIdAndTag(sheetId, tag)) {
722	                sheetTags.save(new SheetTag(sheetId, tag));
723	            }
724	        }
725	    }
726	
727	    public void refuseRefUsed(String sheetId, String ref, Long exceptId) {
728	        if (ref != null && claims.refUsed(sheetId, ref, exceptId)) {
729	            throw new ResponseStatusException(HttpStatus.CONFLICT,
730	                    "The reference \"" + ref + "\" is already used on this sheet");
731	        }
732	    }
733	
734	    private Person person(String sheetId, long personId) {
735	        return people.findByIdAndSheetId(personId, sheetId)
736	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet"));
737	    }
738	
739	    /** An audit record about a claim; one that has a number carries it at the end. */
740	    /** The end of a void's record: its reason, when one was given. */
741	    private static String reasonText(String voidReason) {
742	        return voidReason == null ? "" : " reason=" + voidReason;
743	    }
744	
745	    private static String record(String event, String sheetId, String user, Person person, Claim claim) {
746	        String number = claim.getNumber();
747	        return event + " sheet=" + sheetId + " by=" + user + " person=" + person.getName()
748	                + " amount=" + claim.getAmount().setScale(2).toPlainString() + " date=" + claim.getDate()
749	                + (number != null ? " number=" + number : "");
750	    }
751	}
