package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Set;
import java.util.regex.Pattern;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

/** The paste box: lines of name,amount,date,note, each adding a draft claim for the named person. A
 *  note ending in " #reference" gives the claim that external reference, which is then no part of
 *  the note. */
@Service
public class ClaimPasteService {

    /** The claim form's amount: up to two decimals, a negative one being a correction. */
    private static final Pattern AMOUNT = Pattern.compile("\\s*-?\\d{1,12}(\\.\\d{1,2})?\\s*");

    /** The claim form's longest note. */
    private static final int NOTE_MAX = 500;

    /** The claim form's longest reference. */
    private static final int REF_MAX = 120;

    /** One parsed line: the person, the amount, the date (null: the sheet's today), the note and the
     *  external reference (null: none). */
    private record Line(Person person, BigDecimal amount, LocalDate date, String note, String ref) {
    }

    private final PersonRepository people;
    private final ClaimService claims;

    public ClaimPasteService(PersonRepository people, ClaimService claims) {
        this.people = people;
        this.claims = claims;
    }

    /** Add a draft claim per line, in order, checking every line first; one change, so when any line
     *  is refused nothing is added and nothing is recorded. Blank lines are skipped; a paste with no
     *  lines is refused, and so is one with a reference already used on the sheet or by an earlier
     *  line, comparing without regard to case. Returns how many claims were added. */
    @Transactional
    public int paste(String sheetId, String user, String text) {
        List<Line> lines = new ArrayList<>();
        Set<String> refs = new HashSet<>();
        int n = 0;
        for (String raw : text.split("\\R")) {
            n++;
            if (!raw.isBlank()) {
                Line line = parse(sheetId, n, raw);
                if (line.ref() != null) {
                    if (!refs.add(line.ref().toUpperCase(Locale.ROOT))) {
                        throw refused(n, "the reference \"" + line.ref() + "\" is repeated in the paste");
                    }
                    try {
                        claims.refuseRefUsed(sheetId, line.ref(), null);
                    } catch (ResponseStatusException e) {
                        throw refused(n, "the reference \"" + line.ref() + "\" is already used on this sheet");
                    }
                }
                lines.add(line);
            }
        }
        if (lines.isEmpty()) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "Paste at least one line");
        }
        for (Line line : lines) {
            claims.add(sheetId, user, line.person().getId(), line.amount(), line.date(), line.note(),
                    null, line.ref());
        }
        return lines.size();
    }

    /** A line of name,amount,date,note: the note may hold commas or be absent, the date may be blank. */
    private Line parse(String sheetId, int n, String raw) {
        String[] fields = raw.split(",", 4);
        if (fields.length < 3) {
            throw refused(n, "expected name,amount,date,note");
        }
        String name = fields[0].trim();
        Person person = name.isEmpty() ? null
                : people.findBySheetIdAndNameIgnoreCase(sheetId, name).orElse(null);
        if (person == null) {
            throw refused(n, "no one named \"" + name + "\" on this sheet");
        }
        if (!AMOUNT.matcher(fields[1]).matches()) {
            throw refused(n, "the amount must be a number with up to two decimals");
        }
        BigDecimal amount = new BigDecimal(fields[1].trim()).setScale(2);
        LocalDate date;
        try {
            date = fields[2].isBlank() ? null : LocalDate.parse(fields[2].trim());
        } catch (DateTimeParseException e) {
            throw refused(n, "the date must be YYYY-MM-DD");
        }
        String note = fields.length < 4 ? "" : fields[3].trim();
        String ref = null;
        int hash = note.lastIndexOf(" #");
        if (hash >= 0 && !note.substring(hash + 2).isBlank()) {
            ref = note.substring(hash + 2).trim();
            note = note.substring(0, hash).trim();
        }
        if (note.length() > NOTE_MAX) {
            throw refused(n, "the note is too long");
        }
        if (ref != null && ref.length() > REF_MAX) {
            throw refused(n, "the reference is too long");
        }
        return new Line(person, amount, date, note, ref);
    }

    private static ResponseStatusException refused(int n, String why) {
        return new ResponseStatusException(HttpStatus.BAD_REQUEST, "Line " + n + ": " + why);
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.stereotype.Service;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;
import org.springframework.web.server.ResponseStatusException;

/** Changes made to many claims at once; each claim is changed in its own transaction, so one that
 *  is refused leaves the others as they are, except a settle, which is all or nothing; on an
 *  archived sheet each is refused. */
@Service
public class ClaimBulkService {

    /** How many claims a bulk change made, and how many it refused. */
    public record Outcome(int done, int refused) {
    }

    private final ClaimService claims;
    private final ClaimRepository repository;
    private final PersonRepository people;
    private final SheetService sheets;
    private final TransactionTemplate transactions;
    private final Audit audit;

    public ClaimBulkService(ClaimService claims, ClaimRepository repository, PersonRepository people,
            SheetService sheets, PlatformTransactionManager transactionManager, Audit audit) {
        this.claims = claims;
        this.transactions = new TransactionTemplate(transactionManager);
        this.audit = audit;
        this.sheets = sheets;
        this.repository = repository;
        this.people = people;
    }

    /** Open each of the claims that can be opened, numbering them in list order (people in the
     *  order they were added, newest claim first within a person); each that cannot is refused and
     *  left as it is, and so is an id that names no claim on the sheet. */
    public Outcome open(String sheetId, String user, Set<Long> claimIds) {
        return change(sheetId, user, claimIds, ClaimStatus.OPEN);
    }

    /** Settle all the claims or none: when any of them cannot be settled by the user (any refusal
     *  settling one would give; one a clerk's limit leaves pending is not refused), or an id names no
     *  claim on the sheet, none is settled, each counts as refused and nothing is written. Otherwise
     *  each is settled in list order, exactly as settling one, and they are the sheet's next settle
     *  batch, recorded after their own lines with the frozen dues of those settled added up. */
    public Outcome settle(String sheetId, String user, Set<Long> claimIds) {
        if (sheets.archived(sheetId) || claimIds.isEmpty()) {
            return new Outcome(0, claimIds.size());
        }
        Boolean done = transactions.execute(status -> {
            List<Claim> listed = inListOrder(sheetId, claimIds);
            if (listed.size() != claimIds.size()) {
                status.setRollbackOnly();
                return false;
            }
            List<Long> settled = new ArrayList<>();
            BigDecimal total = BigDecimal.ZERO;
            for (Claim claim : listed) {
                Claim saved;
                try {
                    saved = claims.changeStatus(sheetId, user, claim.getId(), ClaimStatus.SETTLED);
                } catch (ResponseStatusException refused) {
                    // one refused: none is settled, and nothing is written
                    status.setRollbackOnly();
                    return false;
                }
                settled.add(saved.getId());
                if (saved.getStatus() == ClaimStatus.SETTLED && saved.getSettledDue() != null) {
                    total = total.add(saved.getSettledDue());
                }
            }
            // the claims it settled are a batch, numbered next on the sheet
            int batch = claims.markSettleBatch(sheetId, settled);
            audit.recordOnCommit("BATCH_SETTLED sheet=" + sheetId + " by=" + user + " batch=" + batch
                    + " count=" + settled.size() + " total=" + total.setScale(2, RoundingMode.HALF_UP).toPlainString());
            return true;
        });
        return Boolean.TRUE.equals(done) ? new Outcome(claimIds.size(), 0) : new Outcome(0, claimIds.size());
    }

    /** Move each of the claims that can be moved to the person, in list order, exactly as moving
     *  one; each that cannot is refused and left as it is, and so is an id that names no claim on the
     *  sheet. */
    public Outcome reassign(String sheetId, String user, Set<Long> claimIds, long toPersonId) {
        if (sheets.archived(sheetId)) {
            return new Outcome(0, claimIds.size());
        }
        int done = 0;
        for (Claim claim : inListOrder(sheetId, claimIds)) {
            try {
                claims.reassign(sheetId, user, claim.getId(), toPersonId, true);
                done++;
            } catch (ResponseStatusException refused) {
                // left as it is
            }
        }
        return new Outcome(done, claimIds.size() - done);
    }

    private Outcome change(String sheetId, String user, Set<Long> claimIds, ClaimStatus to) {
        if (sheets.archived(sheetId)) {
            return new Outcome(0, claimIds.size());
        }
        int done = 0;
        for (Claim claim : inListOrder(sheetId, claimIds)) {
            try {
                claims.changeStatus(sheetId, user, claim.getId(), to);
                done++;
            } catch (ResponseStatusException refused) {
                // left as it is
            }
        }
        return new Outcome(done, claimIds.size() - done);
    }

    /** The claims of the ids on the sheet in list order: people in the order they were added, newest
     *  claim first within a person. */
    private List<Claim> inListOrder(String sheetId, Set<Long> claimIds) {
        Map<Long, Integer> rank = new HashMap<>();
        List<Person> listed = people.findBySheetIdOrderByIdAsc(sheetId);
        for (int i = 0; i < listed.size(); i++) {
            rank.put(listed.get(i).getId(), i);
        }
        return repository.findBySheetIdOrderByListedDesc(sheetId).stream()
                .filter(c -> claimIds.contains(c.getId()))
                .sorted(Comparator.comparingInt((Claim c) -> rank.getOrDefault(c.getPersonId(), Integer.MAX_VALUE))
                        .thenComparing(Claim::getListed, Comparator.reverseOrder()))
                .toList();
    }
}
package net.officefloor.hq.app.holiday;

import java.time.LocalDate;
import java.util.List;
import java.util.Set;
import java.util.stream.Collectors;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.claim.ClaimStatus;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

/** The holidays of a sheet. */
@Service
public class HolidayService {

    private final HolidayRepository holidays;
    private final SheetService sheets;
    private final ClaimRepository claims;
    private final Rollup rollup;
    private final Audit audit;

    public HolidayService(HolidayRepository holidays, SheetService sheets, ClaimRepository claims, Rollup rollup,
            Audit audit) {
        this.holidays = holidays;
        this.sheets = sheets;
        this.claims = claims;
        this.rollup = rollup;
        this.audit = audit;
    }

    /** The holidays of the sheet, earliest day first. */
    @Transactional(readOnly = true)
    public List<Holiday> list(String sheetId) {
        return holidays.findBySheetIdOrderByDayAsc(sheetId);
    }

    /** Add a day to the sheet's holidays; refused for a day already on the list. Every claim of the
     *  sheet that is not settled or void and is due by the day or later has its due-by fixed again:
     *  the terms-th business day after its date, by the terms it was fixed with, over the holidays
     *  now on the sheet. */
    @Transactional
    public synchronized Holiday add(String sheetId, String user, LocalDate day) {
        sheets.load(sheetId, user);
        if (holidays.existsBySheetIdAndDay(sheetId, day)) {
            throw alreadyListed();
        }
        return rollup.tracking(sheetId, user, () -> {
            Holiday saved;
            try {
                saved = holidays.saveAndFlush(new Holiday(sheetId, day, sheets.today(sheetId)));
            } catch (DataIntegrityViolationException e) {
                throw alreadyListed();
            }
            audit.recordOnCommit("HOLIDAY_ADDED sheet=" + sheetId + " by=" + user + " date=" + day);
            Set<LocalDate> days = holidayDays(sheetId);
            for (Claim claim : claims.findBySheetIdOrderByListedDesc(sheetId)) {
                if (claim.getStatus() == ClaimStatus.SETTLED || claim.getStatus() == ClaimStatus.VOID
                        || claim.getTerms() == null || claim.getDueBy().isBefore(day)) {
                    continue;
                }
                LocalDate dueBy = BusinessDays.after(claim.getDate(), claim.getTerms(), days);
                if (!dueBy.equals(claim.getDueBy())) {
                    claim.refixDueBy(dueBy);
                    claims.save(claim);
                }
            }
            claims.flush();
            return saved;
        });
    }

    /** The terms-th business day after the day (see {@link BusinessDays#after}), skipping every
     *  Saturday, Sunday and holiday of the sheet. */
    @Transactional(readOnly = true)
    public LocalDate businessDaysAfter(String sheetId, LocalDate day, int terms) {
        return BusinessDays.after(day, terms, holidayDays(sheetId));
    }

    private Set<LocalDate> holidayDays(String sheetId) {
        return holidays.findBySheetIdOrderByDayAsc(sheetId).stream().map(Holiday::getDay)
                .collect(Collectors.toSet());
    }

    private static ResponseStatusException alreadyListed() {
        return new ResponseStatusException(HttpStatus.CONFLICT, "That day is already a holiday");
    }
}
package net.officefloor.hq.app.holiday;

import java.time.DayOfWeek;
import java.time.LocalDate;
import java.util.Set;

/** Counting business days: every day but a Saturday, a Sunday or a holiday of the sheet. */
public final class BusinessDays {

    private BusinessDays() {
    }

    /** Whether the day is a business day: not a Saturday, a Sunday or one of the holidays. */
    public static boolean isBusinessDay(LocalDate day, Set<LocalDate> holidays) {
        DayOfWeek dow = day.getDayOfWeek();
        return dow != DayOfWeek.SATURDAY && dow != DayOfWeek.SUNDAY && !holidays.contains(day);
    }

    /** The terms-th business day after the day, counting from the day after it; the day itself when
     *  the terms are none. */
    public static LocalDate after(LocalDate day, int terms, Set<LocalDate> holidays) {
        LocalDate d = day;
        for (int counted = 0; counted < terms;) {
            d = d.plusDays(1);
            if (isBusinessDay(d, holidays)) {
                counted++;
            }
        }
        return d;
    }
}
