import java.math.BigDecimal;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimService;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.person.PersonService;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/** Quick-add: a draft claim for a person named on the sheet, who is added first (at grade A) when
 *  the name is not on the sheet. */
@Service
public class QuickAddService {

    /** The grade a person added by quick-add is given. */
    static final String GRADE = "A";

    /** What a quick-add made: the person the claim is for, whether they were added, and the claim. */
    public record Added(Person person, boolean personAdded, Claim claim) {
    }

    private final PersonRepository people;
    private final PersonService personService;
    private final ClaimService claimService;

    public QuickAddService(PersonRepository people, PersonService personService, ClaimService claimService) {
        this.people = people;
        this.personService = personService;
        this.claimService = claimService;
    }

    /** Add a draft claim of the amount, dated the sheet's entry date (or its today when none is set)
     *  with an empty note, for the person of
     *  the name. One change: when the claim is refused, the person added for it is rolled back too
     *  and nothing is recorded. */
    @Transactional
    public Added add(String sheetId, String user, String name, BigDecimal amount) {
        Person existing = people.findBySheetIdAndNameIgnoreCase(sheetId, name).orElse(null);
        Person person = existing != null ? existing : personService.add(sheetId, user, name, GRADE, null);
        Claim claim = claimService.add(sheetId, user, person.getId(), amount, null, "");
        return new Added(person, existing == null, claim);
    }
}
package net.officefloor.hq.app.watch;

import java.util.List;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Propagation;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

/** The people each user watches on a sheet, and the notices sent them. */
@Service
public class WatchService {

    private final WatchRepository watches;
    private final PersonRepository people;
    private final Audit audit;

    public WatchService(WatchRepository watches, PersonRepository people, Audit audit) {
        this.watches = watches;
        this.people = people;
        this.audit = audit;
    }

    /** The people the user watches on the sheet, in the order they started watching. */
    @Transactional(readOnly = true)
    public List<Watch> list(String sheetId, String user) {
        return watches.findBySheetIdAndUserOrderByIdAsc(sheetId, user);
    }

    /** Start watching a person; refused when the user already watches them. */
    @Transactional
    public Watch watch(String sheetId, String user, long personId) {
        Person person = person(sheetId, personId);
        if (watches.findByPersonIdAndUser(person.getId(), user).isPresent()) {
            throw alreadyWatching();
        }
        Watch saved;
        try {
            saved = watches.saveAndFlush(new Watch(sheetId, person.getId(), user));
        } catch (DataIntegrityViolationException e) {
            throw alreadyWatching();
        }
        audit.recordOnCommit("PERSON_WATCHED sheet=" + sheetId + " by=" + user + " name=" + person.getName());
        return saved;
    }

    /** Stop watching a person; refused when the user does not watch them. */
    @Transactional
    public void unwatch(String sheetId, String user, long personId) {
        Person person = person(sheetId, personId);
        Watch watch = watches.findByPersonIdAndUser(person.getId(), user)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.CONFLICT, "You do not watch this person"));
        watches.delete(watch);
        watches.flush();
        audit.recordOnCommit("PERSON_UNWATCHED sheet=" + sheetId + " by=" + user + " name=" + person.getName());
    }

    /** Tell each user watching the person, in the order they started watching, that a claim of
     *  theirs was settled. Recorded once the change commits, after the records made before it. */
    @Transactional(propagation = Propagation.MANDATORY)
    public void notifyWatchers(String sheetId, String user, Person person, String number) {
        for (Watch watch : watches.findByPersonIdOrderByIdAsc(person.getId())) {
            audit.recordOnCommit("NOTIFY sheet=" + sheetId + " by=" + user + " user=" + watch.getUser()
                    + " person=" + person.getName() + " number=" + number);
        }
    }

    private Person person(String sheetId, long personId) {
        return people.findByIdAndSheetId(personId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet"));
    }

    private static ResponseStatusException alreadyWatching() {
        return new ResponseStatusException(HttpStatus.CONFLICT, "You already watch this person");
    }
}
package net.officefloor.hq.app.voidreason;

import java.util.List;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

/** The void reasons of a sheet. */
@Service
public class VoidReasonService {

    private final VoidReasonRepository reasons;
    private final SheetService sheets;
    private final Audit audit;

    public VoidReasonService(VoidReasonRepository reasons, SheetService sheets, Audit audit) {
        this.reasons = reasons;
        this.sheets = sheets;
        this.audit = audit;
    }

    /** The void reasons of the sheet in the order they were added. */
    @Transactional(readOnly = true)
    public List<VoidReason> list(String sheetId) {
        return reasons.findBySheetIdOrderByIdAsc(sheetId);
    }

    /** Add a (trimmed) reason to the sheet's list; refused when blank or already on the list. */
    @Transactional
    public synchronized VoidReason add(String sheetId, String user, String reason) {
        String text = reason == null ? "" : reason.trim();
        if (text.isEmpty()) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "Enter a void reason");
        }
        sheets.load(sheetId, user);
        if (reasons.existsBySheetIdAndReason(sheetId, text)) {
            throw alreadyListed();
        }
        VoidReason saved;
        try {
            saved = reasons.saveAndFlush(new VoidReason(sheetId, text, sheets.today(sheetId)));
        } catch (DataIntegrityViolationException e) {
            throw alreadyListed();
        }
        audit.recordOnCommit("VOID_REASON_ADDED sheet=" + sheetId + " by=" + user + " reason=" + text);
        return saved;
    }

    /** The reason a claim of the sheet is voided with: null when the sheet has no reasons (none is
     *  needed); refused when it has some and the reason given is not one of them. */
    @Transactional(readOnly = true)
    public String required(String sheetId, String reason) {
        if (!reasons.existsBySheetId(sheetId)) {
            return null;
        }
        String text = reason == null ? "" : reason.trim();
        if (text.isEmpty() || !reasons.existsBySheetIdAndReason(sheetId, text)) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "Choose a void reason from the sheet's list");
        }
        return text;
    }

    private static ResponseStatusException alreadyListed() {
        return new ResponseStatusException(HttpStatus.CONFLICT, "That reason is already on the list");
    }
}
package net.officefloor.hq.app.claim;

import java.util.List;
import java.util.Optional;
import jakarta.persistence.LockModeType;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Lock;
import org.springframework.data.jpa.repository.Modifying;
import org.springframework.data.jpa.repository.Query;

public interface ClaimRepository extends JpaRepository<Claim, Long> {

    /** The claims on a sheet, newest first (the one listed last first). */
    List<Claim> findBySheetIdOrderByListedDesc(String sheetId);

    /** A person's claims on a sheet, newest first (the one listed last first). */
    List<Claim> findBySheetIdAndPersonIdOrderByListedDesc(String sheetId, Long personId);

    Optional<Claim> findByIdAndSheetId(Long id, String sheetId);

    /** A person's claim on a sheet of the number and status. */
    Optional<Claim> findBySheetIdAndPersonIdAndNumberAndStatus(String sheetId, Long personId, String number,
            ClaimStatus status);

    /** Whether a claim on a sheet other than the one given (null: none) has the reference, comparing
     *  without regard to case. */
    @Query("select count(c) > 0 from Claim c where c.sheetId = :sheetId and upper(c.ref) = upper(:ref)"
            + " and (:exceptId is null or c.id <> :exceptId)")
    boolean refUsed(String sheetId, String ref, Long exceptId);

    /** The next place a claim is listed at, after every claim listed so far. */
    @Query(value = "select next value for claim_listed_seq", nativeQuery = true)
    long nextListed();

    /** A claim on a sheet, locked for the rest of the transaction so two status changes to it
     *  happen one after the other. */
    @Lock(LockModeType.PESSIMISTIC_WRITE)
    @Query("select c from Claim c where c.id = :id and c.sheetId = :sheetId")
    Optional<Claim> lockByIdAndSheetId(Long id, String sheetId);

    /** Release every claim editor held open on a sheet (its today changed). */
    @Modifying(flushAutomatically = true)
    @Query("update Claim c set c.editLockedBy = null where c.sheetId = :sheetId and c.editLockedBy is not null")
    int releaseEditLocks(String sheetId);

    /** Release the editors a user holds open on a person's other claims. */
    @Modifying(flushAutomatically = true)
    @Query("update Claim c set c.editLockedBy = null where c.sheetId = :sheetId and c.personId = :personId"
            + " and c.editLockedBy = :user and c.id <> :keepId")
    int releaseOtherEditLocks(String sheetId, Long personId, String user, Long keepId);
}
