39	    /** What the screen shows of a claim; the amount, and the due fixed when it was settled (null
40	     *  when there is none), as text with two decimals; who opened it (null when never opened);
41	     *  whether the last statement bound it, with the due it bound (null when none) and whether it
42	     *  bound it to n/a; and the number
43	     *  of the claim it corrects (null when it is not a correction); the date its figures round by
44	     *  (that of the claim a correction corrects, or else its own); and where it is listed (newest
45	     *  first by this); and its status log, oldest first; and the day it is deferred until (null when
46	     *  never deferred); and how many proofs it has; and the number of the claim it was split off
47	     *  (null when none); and who has its editor open (null when no one); and the last day a reminder
48	     *  was written for it (null when never); and its external reference (null when none); and its tags,
49	     *  sorted and comma and space separated (empty when none); and the reason it was voided with (null
50	     *  when none); and its comments, in the order they were written; and the number of the bulk
51	     *  settle batch that settled it (null when none, or when it is not settled or pending). */
52	    public record ClaimView(long id, long personId, String amount, LocalDate date, String note,
53	            ClaimStatus status, String number, String settledDue, String openedBy, boolean stated,
54	            String statedDue, boolean statedNa, String corrects, LocalDate roundsBy, long listed, LocalDate dueBy,
55	            List<LogLineView> log, LocalDate deferredUntil, int proofs, String splitFrom,
56	            String editLockedBy, boolean lateEntry, LocalDate remindedOn, String ref, String tags,
57	            String voidReason, List<CommentView> comments, Integer settleBatch) {
58	        public static ClaimView of(Claim claim) {
59	            return new ClaimView(claim.getId(), claim.getPersonId(), claim.getAmount().setScale(2).toPlainString(),
60	                    claim.getDate(), claim.getNote(), claim.getStatus(), claim.getNumber(),
61	                    claim.getSettledDue() == null ? null : claim.getSettledDue().setScale(2).toPlainString(),
62	                    claim.getOpenedBy(), claim.isStated(),
63	                    claim.getStatedDue() == null ? null : claim.getStatedDue().setScale(2).toPlainString(),
64	                    claim.isStatedNa(), claim.getCorrects(), claim.roundsBy(), claim.getListed(), claim.getDueBy(),
65	                    claim.getLog().stream().map(LogLineView::of).toList(), claim.getDeferredUntil(),
66	                    claim.getProofs(), claim.getSplitFrom(), claim.getEditLockedBy(), claim.isLateEntry(),
67	                    claim.getRemindedOn(), claim.getRef(), tagsText(claim.getTags()),
68	                    claim.getStatus() == ClaimStatus.VOID ? claim.getVoidReason() : null,
69	                    claim.getComments().stream().map(CommentView::of).toList(),
70	                    batchOf(claim.getStatus(), claim.getSettleBatch()));
71	        }
72	
73	        /** The claim as it stood at the end of a day: its figures as its revision then has them (see
74	         *  {@link History}), its log as far as that day, and its number and who opened it only once it
75	         *  had been opened by then; what no revision keeps (its note, reference, tags, proofs, where it is listed) as it is
76	         *  now (null: the claim is gone now). No one has its editor open then. */
77	        static ClaimView asOf(Claim then, Claim now, LocalDate day) {
78	            Claim kept = now != null ? now : then;
79	            List<ClaimLog> log = kept.getLog().stream().filter(l -> !l.getOn().isAfter(day)).toList();
80	            boolean opened = kept.getLog().isEmpty() ? then.getStatus() != ClaimStatus.DRAFT
81	                    : log.stream().anyMatch(l -> l.getStatus() == ClaimStatus.OPEN);
82	            return new ClaimView(then.getId(), then.getPersonId(), then.getAmount().setScale(2).toPlainString(),
83	                    then.getDate(), kept.getNote(), then.getStatus(), opened ? kept.getNumber() : null,
84	                    then.getSettledDue() == null ? null : then.getSettledDue().setScale(2).toPlainString(),
85	                    opened ? kept.getOpenedBy() : null, then.isStated(),
86	                    then.getStatedDue() == null ? null : then.getStatedDue().setScale(2).toPlainString(),
87	                    then.isStatedNa(), kept.getCorrects(), then.roundsBy(), kept.getListed(), then.getDueBy(),
88	                    log.stream().map(LogLineView::of).toList(), then.getDeferredUntil(), kept.getProofs(),
89	                    kept.getSplitFrom(), null, kept.isLateEntry(),
90	                    kept.getRemindedOn() == null || kept.getRemindedOn().isAfter(day) ? null : kept.getRemindedOn(),
91	                    kept.getRef(), tagsText(kept.getTags()),
92	                    then.getStatus() == ClaimStatus.VOID ? kept.getVoidReason() : null,
93	                    kept.getComments().stream().filter(c -> !c.getOn().isAfter(day)).map(CommentView::of).toList(),
94	                    batchOf(then.getStatus(), kept.getSettleBatch()));
95	        }
96	
97	        /** The settle batch a claim shows: only while it is settled or pending. */
98	        private static Integer batchOf(ClaimStatus status, Integer batch) {
99	            return status == ClaimStatus.SETTLED || status == ClaimStatus.PENDING ? batch : null;
100	        }
101	
102	        /** The tags as the claim shows them: sorted, comma and space separated; empty when none. */
103	        private static String tagsText(String tags) {
104	            return String.join(", ", Tags.of(tags));
105	        }
106	    }
