129	            @Size(max = 120) String ref, @Size(max = 1000) String tags) {
130	
131	        BigDecimal amountValue() {
132	            return new BigDecimal(amount.trim()).setScale(2);
133	        }
134	
135	        String noteValue() {
136	            return note == null ? "" : note.trim();
137	        }
138	
139	        /** The number a correction names (1, 2, ... or P1-1, X-1, ...); null when left blank. */
140	        String correctsValue() {
141	            return corrects == null || corrects.isBlank() ? null : corrects.trim();
142	        }
143	
144	        /** The external reference, its surrounding spaces removed; null when left blank. */
145	        String refValue() {
146	            return ref == null || ref.isBlank() ? null : ref.trim();
147	        }
148	
149	        /** The tags as stored (see {@link Tags}); null when none are named. */
150	        String tagsValue() {
151	            return Tags.normalise(tags);
152	        }
153	    }
