188	    /** The claims on the sheet, newest first; as of a day when one is given, as they stood at the end
189	     *  of it (see {@link History}). */
190	    @GetMapping("/claims")
191	    public List<ClaimView> list(@PathVariable @NotBlank @Size(max = 100) String sheetId,
192	            @RequestHeader(value = AsOfGuard.HEADER, required = false) @DateTimeFormat(iso = DateTimeFormat.ISO.DATE)
193	            LocalDate asOf) {
194	        String sheet = sheetId.trim();
195	        if (asOf != null) {
196	            Map<Long, Claim> now = service.list(sheet).stream()
197	                    .collect(Collectors.toMap(Claim::getId, Function.identity()));
198	            return history.asOf(sheet, asOf).claims().stream()
199	                    .map(then -> ClaimView.asOf(then, now.get(then.getId()), asOf))
200	                    .sorted(Comparator.comparingLong(ClaimView::listed).reversed()).toList();
201	        }
202	        return service.list(sheet).stream().map(ClaimView::of).toList();
203	    }
