505	    /** The actions the permission matrix covers. */
506	    public static final List<String> ACTIONS = List.of("open", "settle", "void", "reassign", "close", "reopen");
507	
508	    /** The roles that may take each action under the standing rule (a blank entry in the matrix). */
509	    private static final Map<String, List<String>> STANDING_PERMISSIONS = Map.of(
510	            "open", List.of("clerk", "steward"), "settle", List.of("clerk", "steward"),
511	            "void", List.of("clerk", "steward"), "close", List.of("clerk", "steward"),
512	            "reassign", List.of("steward"), "reopen", List.of("steward"));
513	
514	    /** The permission matrix as set on the sheet: for each action, the comma separated roles that may
515	     *  take it, blank ("") when it keeps the standing rule. */
516	    @Transactional(readOnly = true)
517	    public Map<String, String> permissions(String id) {
518	        Map<String, String> matrix = new TreeMap<>();
519	        for (String action : ACTIONS) {
520	            matrix.put(action, "");
521	        }
522	        for (SheetPermission p : permissions.findBySheetId(id)) {
523	            matrix.put(p.getAction(), p.getRoles());
524	        }
525	        return matrix;
526	    }
527	
528	    /** The roles that may take an action on the sheet: those set in the matrix, or else the standing
529	     *  rule's. */
530	    @Transactional(readOnly = true)
531	    public List<String> rolesAllowed(String id, String action) {
532	        return permissions.findById(new SheetPermission.Key(id, action))
533	                .map(p -> List.of(p.getRoles().split(",")))
534	                .orElse(STANDING_PERMISSIONS.get(action));
535	    }
536	
537	    /** Set the roles (a comma separated list; blank: the standing rule) that may take an action on the
538	     *  sheet; recorded even when it is unchanged. */
539	    @Transactional
540	    public synchronized Sheet setPermission(String id, String user, String action, String roles) {
541	        Sheet sheet = load(id, user);
542	        if (roles.isEmpty()) {
543	            permissions.deleteById(new SheetPermission.Key(id, action));
544	        } else {
545	            SheetPermission p = permissions.findById(new SheetPermission.Key(id, action))
546	                    .orElseGet(() -> new SheetPermission(id, action, roles));
547	            p.setRoles(roles);
548	            permissions.saveAndFlush(p);
549	        }
550	        audit.recordOnCommit("SETTING_CHANGED sheet=" + id + " by=" + user + " key=perm-" + action + " value=" + roles);
551	        return sheet;
552	    }
553	}
554	package net.officefloor.hq.app.role;
555	
556	import java.time.LocalDate;
557	import java.util.List;
558	import java.util.Optional;
559	import net.officefloor.hq.app.Audit;
560	import net.officefloor.hq.app.sheet.SheetService;
561	import org.springframework.stereotype.Service;
562	import org.springframework.http.HttpStatus;
563	import org.springframework.transaction.annotation.Transactional;
564	import org.springframework.web.server.ResponseStatusException;
565	
566	/** The roles user names have on a sheet: clerk (the default for any name), steward or viewer
567	 *  (who may change nothing); and the steward role a steward delegates to a user name for a range of
568	 *  days, inside which, by the sheet's today, the user acts as a steward. */
569	@Service
570	public class RoleService {
571	
572	    private final SheetRoleRepository roles;
573	    private final DelegationRepository delegations;
574	    private final SheetService sheets;
575	    private final Audit audit;
576	
577	    public RoleService(SheetRoleRepository roles, DelegationRepository delegations, SheetService sheets, Audit audit) {
578	        this.roles = roles;
579	        this.delegations = delegations;
580	        this.sheets = sheets;
581	        this.audit = audit;
582	    }
583	
584	    /** The roles given on the sheet, by user name. */
585	    @Transactional(readOnly = true)
586	    public List<SheetRole> list(String sheetId) {
587	        return roles.findBySheetIdOrderByUserNameAsc(sheetId);
588	    }
589	
590	    /** The role a user name acts in on the sheet: steward while a delegation to it holds the sheet's
591	     *  today, else the role it was given. */
592	    @Transactional(readOnly = true)
593	    public String roleOf(String sheetId, String userName) {
594	        return delegatorOf(sheetId, userName).isPresent() ? SheetRole.STEWARD : givenRoleOf(sheetId, userName);
595	    }
596	
597	    /** The role given to a user name on the sheet: clerk unless it was given another. */
598	    @Transactional(readOnly = true)
599	    public String givenRoleOf(String sheetId, String userName) {
600	        return roles.findBySheetIdAndUserName(sheetId, userName).map(SheetRole::getRole).orElse(SheetRole.CLERK);
601	    }
602	
603	    /** The steward a user name acts for on the sheet: the one who delegated the steward role to it
604	     *  for a range holding the sheet's today (the latest such delegation). */
605	    @Transactional(readOnly = true)
606	    public Optional<String> delegatorOf(String sheetId, String userName) {
607	        LocalDate today = sheets.today(sheetId);
608	        return delegations
609	                .findFirstBySheetIdAndUserNameAndFromDateLessThanEqualAndToDateGreaterThanEqualOrderByIdDesc(
610	                        sheetId, userName, today, today)
611	                .map(Delegation::getDelegatedBy);
612	    }
613	
614	    /** The delegations made on the sheet, in the order they were made. */
615	    @Transactional(readOnly = true)
616	    public List<Delegation> delegations(String sheetId) {
617	        return delegations.findBySheetIdOrderByIdAsc(sheetId);
618	    }
619	
620	    /** Delegate the steward role to a user name from a day (the sheet's today when none) to a day (the
621	     *  from-day when none), inclusive. Refused unless the user was given the steward role, or when the
622	     *  range ends before it starts. */
623	    @Transactional
624	    public synchronized Delegation delegate(String sheetId, String user, String userName, LocalDate from, LocalDate to) {
625	        sheets.load(sheetId, user);
626	        if (!SheetRole.STEWARD.equals(givenRoleOf(sheetId, user))) {
627	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward may delegate the steward role");
628	        }
629	        LocalDate start = from == null ? sheets.today(sheetId) : from;
630	        LocalDate end = to == null ? start : to;
631	        if (end.isBefore(start)) {
632	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "A delegation cannot end before it starts");
633	        }
634	        Delegation saved = delegations.saveAndFlush(new Delegation(sheetId, userName, user, start, end));
635	        audit.recordOnCommit("DELEGATED sheet=" + sheetId + " by=" + user + " user=" + userName
636	                + " from=" + start + " to=" + end);
637	        return saved;
638	    }
639	
640	    /** Whether a user name's role on the sheet may take an action of the permission matrix (open,
641	     *  settle, void, reassign, close, reopen). */
642	    @Transactional(readOnly = true)
643	    public boolean may(String sheetId, String userName, String action) {
644	        return sheets.rolesAllowed(sheetId, action).contains(roleOf(sheetId, userName));
645	    }
646	
647	    /** Give a user name a role on the sheet, replacing the one it had. */
648	    @Transactional
649	    public synchronized SheetRole set(String sheetId, String user, String userName, String role) {
650	        sheets.load(sheetId, user);
651	        SheetRole given = roles.findBySheetIdAndUserName(sheetId, userName)
652	                .orElseGet(() -> new SheetRole(sheetId, userName, role));
653	        given.setRole(role);
654	        SheetRole saved = roles.saveAndFlush(given);
655	        audit.recordOnCommit("ROLE_SET sheet=" + sheetId + " by=" + user + " user=" + userName + " role=" + role);
656	        return saved;
657	    }
658	}
