733	/** Refuses every change a viewer asks of a sheet (403), before it writes anything; only the
734	 *  requests marked {@link ViewerAllowed} go through. */
735	@Configuration
736	public class ViewerGuard implements HandlerInterceptor, WebMvcConfigurer {
737	
738	    private final RoleService roles;
739	
740	    public ViewerGuard(RoleService roles) {
741	        this.roles = roles;
742	    }
743	
744	    @Override
745	    public void addInterceptors(InterceptorRegistry registry) {
746	        registry.addInterceptor(this).addPathPatterns("/api/sheets/**");
747	    }
748	
749	    @Override
