67	        if (periods.existsBySheetIdAndNameIgnoreCase(sheetId, name)) {
68	            throw nameInUse();
69	        }
70	        if (periods.overlaps(sheetId, from, to)) {
71	            throw new ResponseStatusException(HttpStatus.CONFLICT, "That period overlaps another on this sheet");
72	        }
73	        Period saved;
74	        try {
75	            saved = periods.saveAndFlush(new Period(sheetId, name, from, to));
76	        } catch (DataIntegrityViolationException e) {
77	            throw nameInUse();
78	        }
79	        audit.recordOnCommit("PERIOD_ADDED sheet=" + sheetId + " by=" + user + " period=" + saved.getName()
80	                + " from=" + saved.getFromDate() + " to=" + saved.getToDate());
81	        history.record(sheetId);
82	        return saved;
83	    }
84	
85	    /** Generate one period per calendar month from the from-date's month to the to-date's month
86	     *  (the from-date the sheet's today when none is given), each running from the first to the last
87	     *  day of its month and named yyyy-mm; a month whose name is in use on the sheet, or whose days
88	     *  overlap a period on it, is left out. Refused when the to-date is before the from-date. */
89	    @Transactional
90	    public synchronized List<Period> generate(String sheetId, String user, LocalDate from, LocalDate to) {
91	        sheets.load(sheetId, user);
92	        if (from == null) {
93	            from = sheets.today(sheetId);
94	        }
95	        if (to.isBefore(from)) {
96	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "The to-date cannot be before the from-date");
97	        }
98	        List<Period> made = new ArrayList<>();
99	        for (YearMonth month = YearMonth.from(from); !month.isAfter(YearMonth.from(to)); month = month.plusMonths(1)) {
100	            String name = month.toString();
101	            LocalDate first = month.atDay(1);
102	            LocalDate last = month.atEndOfMonth();
103	            if (periods.existsBySheetIdAndNameIgnoreCase(sheetId, name) || periods.overlaps(sheetId, first, last)) {
104	                continue;
105	            }
106	            Period saved = periods.saveAndFlush(new Period(sheetId, name, first, last));
107	            audit.recordOnCommit("PERIOD_ADDED sheet=" + sheetId + " by=" + user + " period=" + saved.getName()
108	                    + " from=" + saved.getFromDate() + " to=" + saved.getToDate());
109	            made.add(saved);
110	        }
111	        history.record(sheetId);
112	        return made;
113	    }
114	
115	    /** Close a period (an open or a soft-closed one), fixing its due-total at what it is now; refused when the permission matrix does
116	     *  not allow the user's role to close, or it is already closed. */
117	    @Transactional
118	    public Period close(String sheetId, String user, long periodId) {
119	        sheets.load(sheetId, user);
120	        if (!roles.may(sheetId, user, "close")) {
121	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Your role may not close a period");
122	        }
123	        Period period = periods.lockByIdAndSheetId(periodId, sheetId)
124	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such period on this sheet"));
125	        if (period.isClosed()) {
126	            throw new ResponseStatusException(HttpStatus.CONFLICT, "That period is already closed");
127	        }
128	        return closeOpen(sheetId, user, period, "");
129	    }
130	
131	    /** Soft-close a period, fixing its due-total and each person's for it at what they are now while
132	     *  claims dated inside it stay open to change; refused when the permission matrix does not allow
133	     *  the user's role to close, or it is already closed or soft-closed. */
134	    @Transactional
135	    public Period softClose(String sheetId, String user, long periodId) {
136	        sheets.load(sheetId, user);
137	        if (!roles.may(sheetId, user, "close")) {
138	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Your role may not close a period");
139	        }
140	        Period period = periods.lockByIdAndSheetId(periodId, sheetId)
141	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such period on this sheet"));
142	        if (period.isClosed() || period.isSoftClosed()) {
143	            throw new ResponseStatusException(HttpStatus.CONFLICT, "That period is already closed");
144	        }
145	        period.softClose(personTotals(sheetId, period));
146	        Period saved = periods.saveAndFlush(period);
147	        audit.recordOnCommit("PERIOD_SOFT_CLOSED sheet=" + sheetId + " by=" + user + " period=" + saved.getName()
148	                + " total=" + saved.getClosedTotal().toPlainString());
149	        history.record(sheetId);
150	        return saved;
151	    }
152	
153	    /** Close every open period on the sheet whose to-date plus the grace days is before the day,
154	     *  earliest to-date first, each as a close by hand would, its record marked auto=yes. */
155	    @Transactional(propagation = Propagation.MANDATORY)
156	    public void autoClose(String sheetId, String user, int graceDays, LocalDate day) {
157	        for (Period period : periods.findOpenEndingBefore(sheetId, day.minusDays(graceDays))) {
158	            closeOpen(sheetId, user, period, " auto=yes");
159	        }
160	    }
161	
162	    /** Close an open period, fixing its due-total at what it is now; the suffix ends its record. */
163	    private Period closeOpen(String sheetId, String user, Period period, String suffix) {
164	        period.close(personTotals(sheetId, period));
165	        Period saved = periods.saveAndFlush(period);
166	        audit.recordOnCommit("PERIOD_CLOSED sheet=" + sheetId + " by=" + user + " period=" + saved.getName()
167	                + " total=" + saved.getClosedTotal().toPlainString() + suffix);
168	        history.record(sheetId);
169	        return saved;
170	    }
171	
172	    /** Reopen a closed or soft-closed period, making its due-total live again; refused when the permission matrix
173	     *  does not allow the user's role to reopen, or the period is not closed. */
174	    @Transactional
175	    public Period reopen(String sheetId, String user, long periodId) {
176	        sheets.load(sheetId, user);
177	        if (!roles.may(sheetId, user, "reopen")) {
178	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Your role may not reopen a period");
179	        }
180	        Period period = periods.lockByIdAndSheetId(periodId, sheetId)
181	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such period on this sheet"));
182	        if (!period.isClosed() && !period.isSoftClosed()) {
183	            throw new ResponseStatusException(HttpStatus.CONFLICT, "That period is not closed");
184	        }
185	        period.reopen();
186	        Period saved = periods.saveAndFlush(period);
187	        audit.recordOnCommit("PERIOD_REOPENED sheet=" + sheetId + " by=" + user + " period=" + saved.getName());
188	        history.record(sheetId);
189	        return saved;
190	    }
191	
192	    /** Each person's due-total for a period, by the person's id: the due figures of their claims
193	     *  whose due-by falls in it and that count by their status at its end, skipping those with no due
194	     *  and those the live rules leave out (see Dues#countsAsOf). */
195	    private Map<Long, BigDecimal> personTotals(String sheetId, Period period) {
196	        Map<Long, Person> byId = people.findBySheetIdOrderByIdAsc(sheetId).stream()
197	                .collect(Collectors.toMap(Person::getId, Function.identity()));
198	        Map<Long, BigDecimal> totals = new HashMap<>();
199	        for (Long id : byId.keySet()) {
200	            totals.put(id, BigDecimal.ZERO.setScale(2));
201	        }
202	        LocalDate today = sheets.today(sheetId);
203	        for (Claim c : claims.findBySheetIdOrderByListedDesc(sheetId)) {
204	            Person person = byId.get(c.getPersonId());
205	            if (person == null || !Dues.countsAsOf(person, c, period.getToDate(), today) || c.getDueBy().isBefore(period.getFromDate())
206	                    || c.getDueBy().isAfter(period.getToDate())) {
207	                continue;
208	            }
209	            BigDecimal figure = dues.figure(sheetId, person, c);
210	            if (figure != null) {
211	                totals.merge(person.getId(), figure, BigDecimal::add);
212	            }
213	        }
214	        return totals;
215	    }
216	
217	    private static ResponseStatusException nameInUse() {
218	        return new ResponseStatusException(HttpStatus.CONFLICT, "That period name is already in use on this sheet");
219	    }
220	}
