262	    int advanceClaimNumber(Long id);
263	
264	    @Query("select p.lastClaimNumber from Period p where p.id = :id")
265	    int lastClaimNumber(Long id);
266	
267	    /** A period on a sheet, locked for the rest of the transaction so two closes or reopens of
268	     *  it happen one after the other. */
269	    @Lock(LockModeType.PESSIMISTIC_WRITE)
270	    @Query("select p from Period p where p.id = :id and p.sheetId = :sheetId")
271	    Optional<Period> lockByIdAndSheetId(Long id, String sheetId);
272	
273	    /** The open periods (neither closed nor soft-closed) on a sheet whose to-date is before the day, earliest to-date first. */
274	    @Query("select p from Period p where p.sheetId = :sheetId and p.closed = false and p.softClosed = false and p.toDate < :day"
275	            + " order by p.toDate asc")
276	    List<Period> findOpenEndingBefore(String sheetId, LocalDate day);
