280	import jakarta.persistence.CollectionTable;
281	import jakarta.persistence.Column;
282	import jakarta.persistence.ElementCollection;
283	import jakarta.persistence.FetchType;
284	import jakarta.persistence.JoinColumn;
285	import jakarta.persistence.MapKeyColumn;
286	import jakarta.persistence.Entity;
287	import jakarta.persistence.GeneratedValue;
288	import jakarta.persistence.GenerationType;
289	import jakarta.persistence.Id;
