291	import java.math.BigDecimal;
292	import java.time.LocalDate;
293	import java.util.HashMap;
294	import java.util.Map;
295	
296	/** A period on a sheet: a named run of days from its from-date to its to-date, both inclusive. A
297	 *  claim belongs to the period whose days contain its due-by. A closed period keeps the due-total it
298	 *  had when it was closed, and no claim due by a day inside it can be changed. A soft-closed period
299	 *  keeps its due-total as a closed one does, but claims due inside it can still be added and changed. */
300	@Entity
301	@Table(name = "period")
302	public class Period {
303	
304	    @Id
305	    @GeneratedValue(strategy = GenerationType.IDENTITY)
306	    private Long id;
307	
308	    @Column(name = "sheet_id", nullable = false)
309	    private String sheetId;
310	
311	    @Column(name = "name", nullable = false)
312	    private String name;
313	
314	    @Column(name = "from_date", nullable = false)
315	    private LocalDate fromDate;
316	
317	    @Column(name = "to_date", nullable = false)
318	    private LocalDate toDate;
319	
320	    @Column(name = "closed", nullable = false)
321	    private boolean closed;
322	
323	    @Column(name = "soft_closed", nullable = false)
324	    private boolean softClosed;
325	
326	    @Column(name = "closed_total")
327	    private BigDecimal closedTotal;
328	
329	    /** Each person's due-total for the period, by the person's id, fixed when it was closed; empty
330	     *  while it is open. */
331	    @ElementCollection(fetch = FetchType.EAGER)
332	    @CollectionTable(name = "period_person_total", joinColumns = @JoinColumn(name = "period_id"))
333	    @MapKeyColumn(name = "person_id")
334	    @Column(name = "total", nullable = false)
335	    private Map<Long, BigDecimal> personTotals = new HashMap<>();
336	
337	    /** The last number given to a claim in the period under period numbering; only ever moved on by
338	     *  {@link PeriodRepository#advanceClaimNumber}. */
339	    @Column(name = "last_claim_number", insertable = false, updatable = false)
340	    private int lastClaimNumber;
341	
342	    protected Period() {
343	    }
344	
345	    /** A period as a revision in its sheet's history has it, detached: never saved. */
346	    static Period revised(String sheetId, Long id, String name, LocalDate fromDate, LocalDate toDate,
347	            boolean closed, boolean softClosed, BigDecimal closedTotal, Map<Long, BigDecimal> personTotals) {
348	        Period period = new Period(sheetId, name, fromDate, toDate);
349	        period.id = id;
350	        period.closed = closed;
351	        period.softClosed = softClosed;
352	        period.closedTotal = closedTotal;
353	        period.personTotals.putAll(personTotals);
354	        return period;
355	    }
356	
357	    public Period(String sheetId, String name, LocalDate fromDate, LocalDate toDate) {
358	        this.sheetId = sheetId;
359	        this.name = name;
360	        this.fromDate = fromDate;
361	        this.toDate = toDate;
362	    }
363	
364	    public Long getId() {
365	        return id;
366	    }
367	
368	    public String getSheetId() {
369	        return sheetId;
370	    }
371	
372	    public String getName() {
373	        return name;
374	    }
375	
376	    public LocalDate getFromDate() {
377	        return fromDate;
378	    }
379	
380	    public LocalDate getToDate() {
381	        return toDate;
382	    }
383	
384	    public boolean isClosed() {
385	        return closed;
386	    }
387	
388	    public boolean isSoftClosed() {
389	        return softClosed;
390	    }
391	
392	    /** The due-total fixed when the period was closed or soft-closed; null while it is open. */
393	    public BigDecimal getClosedTotal() {
394	        return closedTotal;
395	    }
396	
397	    /** Each person's due-total fixed when the period was closed, by the person's id; empty while it
398	     *  is open. */
399	    public Map<Long, BigDecimal> getPersonTotals() {
400	        return Map.copyOf(personTotals);
401	    }
402	
403	    /** Close the period, fixing each person's due-total for it at what it is now, and its own
404	     *  due-total at their sum. */
405	    public void close(Map<Long, BigDecimal> personTotals) {
406	        this.closed = true;
407	        this.softClosed = false;
408	        fix(personTotals);
409	    }
410	
411	    /** Soft-close the period, fixing its due-totals as {@link #close} does while leaving claims dated
412	     *  inside it open to change. */
413	    public void softClose(Map<Long, BigDecimal> personTotals) {
414	        this.softClosed = true;
415	        fix(personTotals);
416	    }
417	
418	    private void fix(Map<Long, BigDecimal> personTotals) {
419	        this.personTotals.clear();
420	        this.personTotals.putAll(personTotals);
421	        this.closedTotal = personTotals.values().stream().reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
422	    }
423	
424	    /** Reopen the period: its due-total is live again. */
425	    public void reopen() {
426	        this.closed = false;
427	        this.softClosed = false;
428	        this.closedTotal = null;
429	        this.personTotals.clear();
430	    }
431	}
