434	import java.math.BigDecimal;
435	import java.time.LocalDate;
436	import java.util.List;
437	import java.util.Map;
438	import java.util.stream.Collectors;
439	import net.officefloor.hq.app.Audit;
440	import net.officefloor.hq.app.claim.Claim;
441	import net.officefloor.hq.app.claim.ClaimRepository;
442	import net.officefloor.hq.app.claim.Dues;
443	import net.officefloor.hq.app.history.History;
444	import net.officefloor.hq.app.rollup.Rollup;
445	import net.officefloor.hq.app.person.Person;
446	import net.officefloor.hq.app.person.PersonRepository;
447	import net.officefloor.hq.app.role.RoleService;
448	import net.officefloor.hq.app.role.SheetRole;
449	import net.officefloor.hq.app.sheet.SheetService;
450	import org.springframework.http.HttpStatus;
451	import org.springframework.stereotype.Service;
452	import org.springframework.transaction.annotation.Transactional;
453	import org.springframework.web.server.ResponseStatusException;
454	
455	/** The statements taken of people on a sheet. */
456	@Service
457	public class StatementService {
458	
459	    /** A statement just taken: the person, what their statements now come to, and their claims
460	     *  (newest first) as the statement bound them. */
461	    public record Taken(Person person, StatementSummary summary, List<Claim> claims) {
462	    }
463	
464	    private final StatementRepository statements;
465	    private final PersonRepository people;
466	    private final ClaimRepository claims;
467	    private final Dues dues;
468	    private final SheetService sheets;
469	    private final Rollup rollup;
470	    private final RoleService roles;
471	    private final History history;
472	    private final Audit audit;
473	
474	    public StatementService(StatementRepository statements, PersonRepository people, ClaimRepository claims,
475	            Dues dues, SheetService sheets, Rollup rollup, RoleService roles, History history, Audit audit) {
476	        this.history = history;
477	        this.statements = statements;
478	        this.people = people;
479	        this.claims = claims;
480	        this.dues = dues;
481	        this.sheets = sheets;
482	        this.rollup = rollup;
483	        this.roles = roles;
484	        this.audit = audit;
485	    }
486	
487	    /** What each person's statements on the sheet come to, by person id; a person with none is
488	     *  missing. */
489	    @Transactional(readOnly = true)
490	    public Map<Long, StatementSummary> summaries(String sheetId) {
491	        return statements.findBySheetIdOrderByIdAsc(sheetId).stream()
492	                .collect(Collectors.groupingBy(Statement::getPersonId,
493	                        Collectors.collectingAndThen(Collectors.toList(), StatementSummary::of)));
494	    }
495	
496	    /** What each person's statements on the sheet came to at the end of a day: those taken while the
497	     *  sheet's today was on or before it, by person id; a person with none is missing. */
498	    @Transactional(readOnly = true)
499	    public Map<Long, StatementSummary> summaries(String sheetId, LocalDate day) {
500	        return statements.findBySheetIdOrderByIdAsc(sheetId).stream()
501	                .filter(s -> !s.getTakenOn().isAfter(day))
502	                .collect(Collectors.groupingBy(Statement::getPersonId,
503	                        Collectors.collectingAndThen(Collectors.toList(), StatementSummary::of)));
504	    }
505	
506	    /** What one person's statements come to. */
507	    @Transactional(readOnly = true)
508	    public StatementSummary summary(String sheetId, long personId) {
509	        return StatementSummary.of(statements.findBySheetIdAndPersonIdOrderByIdAsc(sheetId, personId));
510	    }
511	
512	    /** Take a statement of a person: record their due-total now and bind each of their claims that
513	     *  counts in the live totals to the rate figure it has now, leaving out any late charge and the floor; any other
514	     *  claim (one that does not count, a deferred one, or an open unbound one dated within one of their
515	     *  holds) is unbound. */
516	    @Transactional
517	    public Taken take(String sheetId, String user, long personId) {
518	        return take(sheetId, user, personId, null);
519	    }
520	
521	    /** Take a statement of a person as of a day (null: the sheet's today) on or before the sheet's
522	     *  today: the sheet as it stood at the end of that day (see {@link History}) stands in for it as
523	     *  it is now, that day for its today. Their due-total then is recorded, and each claim of theirs
524	     *  that counted in the live totals then is bound to the rate figure it had then; every other claim
525	     *  of theirs is unbound. Refused when the day is after the sheet's today, or when the person was
526	     *  not on the sheet yet then. */
527	    @Transactional
528	    public Taken take(String sheetId, String user, long personId, LocalDate asOf) {
529	        LocalDate today = sheets.today(sheetId);
530	        if (asOf != null && asOf.isAfter(today)) {
531	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
532	                    "A statement cannot be taken as of a day after the sheet's today");
533	        }
534	        Person person = people.lockByIdAndSheetId(personId, sheetId)
535	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet"));
536	        History.SheetAsOf then = asOf == null ? null : history.asOf(sheetId, asOf);
537	        Person was = then == null ? person : then.person(personId)
538	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.CONFLICT,
539	                        "The person was not on the sheet yet on that day"));
540	        List<Claim> bound = rollup.tracking(sheetId, user, () -> {
541	            List<Claim> theirs = claims.findBySheetIdAndPersonIdOrderByListedDesc(sheetId, personId);
542	            Dues.Basis basis = then == null ? dues.now(sheetId) : then.basis();
543	            List<Claim> counted = Dues.live(was, then == null ? theirs : then.claimsOf(personId), basis.today());
544	            BigDecimal dueTotal = dues.dueTotal(basis, was, counted);
545	            Map<Long, Claim> countedById = counted.stream().collect(Collectors.toMap(Claim::getId, c -> c));
546	            for (Claim claim : theirs) {
547	                Claim figured = countedById.get(claim.getId());
548	                if (figured != null) {
549	                    claim.bind(true, dues.bindable(basis, was, figured), dues.bindsNa(basis, was, figured));
550	                } else {
551	                    claim.bind(false, null);
552	                }
553	            }
554	            claims.saveAllAndFlush(theirs);
555	            statements.saveAndFlush(new Statement(sheetId, personId, today, user, dueTotal, counted.size(), asOf));
556	            audit.recordOnCommit("STATEMENT sheet=" + sheetId + " by=" + user + " name=" + person.getName()
557	                    + " due-total=" + (dueTotal == null ? "n/a" : dueTotal.setScale(2).toPlainString())
558	                    + " claims=" + counted.size() + (asOf != null ? " asof=" + asOf : ""));
559	            return theirs;
560	        });
561	        return new Taken(person, summary(sheetId, personId), bound);
562	    }
563	
564	    /** Cancel a person's last statement: only a steward may, and only when one was taken. The claims
565	     *  it bound become live again (a figure an earlier statement bound is not restored), and the
566	     *  statement before it, if any, becomes their last. */
567	    @Transactional
568	    public Taken cancelLast(String sheetId, String user, long personId) {
569	        if (!SheetRole.STEWARD.equals(roles.roleOf(sheetId, user))) {
570	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward can cancel a statement");
571	        }
572	        Person person = people.lockByIdAndSheetId(personId, sheetId)
573	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet"));
574	        List<Statement> taken = statements.findBySheetIdAndPersonIdOrderByIdAsc(sheetId, personId);
575	        if (taken.isEmpty()) {
576	            throw new ResponseStatusException(HttpStatus.CONFLICT, "No statement has been taken of this person");
577	        }
578	        Statement last = taken.get(taken.size() - 1);
579	        List<Claim> unbound = rollup.tracking(sheetId, user, () -> {
580	            List<Claim> theirs = claims.findBySheetIdAndPersonIdOrderByListedDesc(sheetId, personId);
581	            theirs.forEach(claim -> claim.bind(false, null));
582	            claims.saveAllAndFlush(theirs);
583	            statements.delete(last);
584	            statements.flush();
585	            audit.recordOnCommit("STATEMENT_CANCELLED sheet=" + sheetId + " by=" + user + " name=" + person.getName()
586	                    + " due-total=" + (last.getDueTotal() == null ? "n/a" : last.getDueTotal().setScale(2).toPlainString()));
587	            return theirs;
588	        });
589	        return new Taken(person, summary(sheetId, personId), unbound);
590	    }
591	}
