612	/** The rates for each grade on a sheet, each applying from its from-date. */
613	@Service
614	public class RateService {
615	
616	    private final RateRepository rates;
617	    private final SheetService sheets;
618	    private final Rollup rollup;
619	    private final Audit audit;
620	    private final Dues dues;
