624	    public RateService(RateRepository rates, SheetService sheets, Rollup rollup, Audit audit, Dues dues,
625	            PersonRepository people, ClaimRepository claims) {
626	        this.rates = rates;
627	        this.sheets = sheets;
628	        this.rollup = rollup;
629	        this.audit = audit;
630	        this.dues = dues;
631	        this.people = people;
