635	    /** What a candidate rate would change: how many claims would show a different due, and the sum of
636	     *  the differences (new due minus current due; a due of n/a taken as 0.00). */
637	    public record Preview(int count, BigDecimal diff) {
638	    }
639	
640	    /** Preview a candidate rate applying to a grade on every date: the open and pending claims of
641	     *  people on that grade (the grade in force on the claim's date) whose due would differ. A claim
642	     *  bound by a statement keeps its bound figure; a settled claim is not counted. Saves nothing. */
643	    @Transactional(readOnly = true)
644	    public Preview preview(String sheetId, String grade, BigDecimal pct) {
645	        Dues.Basis now = dues.now(sheetId);
646	        List<Rate> candidate = List.of(new Rate(sheetId, grade, pct, null));
647	        Dues.Basis with = new Dues.Basis() {
648	            @Override
649	            public LocalDate today() {
650	                return now.today();
651	            }
652	
653	            @Override
654	            public BigDecimal floor(LocalDate day) {
655	                return now.floor(day);
656	            }
657	
658	            @Override
659	            public BigDecimal latePct(LocalDate day) {
660	                return now.latePct(day);
661	            }
662	
663	            @Override
664	            public BigDecimal cap() {
665	                return now.cap();
666	            }
667	
668	            @Override
669	            public LocalDate policyDateInForce() {
670	                return now.policyDateInForce();
671	            }
672	
673	            @Override
674	            public List<Rate> rates(String g) {
675	                return g.equals(grade) ? candidate : now.rates(g);
676	            }
677	
678	            @Override
679	            public int grace(String g, LocalDate day) {
680	                return now.grace(g, day);
681	            }
682	        };
683	        Map<Long, Person> byId = people.findBySheetIdOrderByIdAsc(sheetId).stream()
684	                .collect(Collectors.toMap(Person::getId, Function.identity()));
685	        BigDecimal zero = BigDecimal.ZERO.setScale(2);
686	        int count = 0;
687	        BigDecimal diff = zero;
688	        for (Claim claim : claims.findBySheetIdOrderByListedDesc(sheetId)) {
689	            Person person = byId.get(claim.getPersonId());
690	            if (person == null || (claim.getStatus() != ClaimStatus.OPEN && claim.getStatus() != ClaimStatus.PENDING)
691	                    || !grade.equals(person.gradeOn(claim.getDate()))) {
692	                continue;
693	            }
694	            BigDecimal was = dues.figure(now, person, claim);
695	            BigDecimal would = dues.figure(with, person, claim);
696	            BigDecimal wasValue = was == null ? zero : was;
697	            BigDecimal wouldValue = would == null ? zero : would;
698	            if ((was == null) != (would == null) || wasValue.compareTo(wouldValue) != 0) {
699	                count++;
700	                diff = diff.add(wouldValue.subtract(wasValue));
701	            }
702	        }
703	        return new Preview(count, diff.setScale(2));
704	    }
