712	    /** Set the rate for a grade from a date (null: from the beginning of time) through a date
713	     *  (null: no end), replacing the one the grade had for that from-date. */
714	    @Transactional
715	    public synchronized Rate set(String sheetId, String user, String grade, BigDecimal pct, LocalDate from,
716	            LocalDate to) {
