719	            Rate rate = (from == null
720	                    ? rates.findBySheetIdAndGradeAndFromDateIsNull(sheetId, grade)
721	                    : rates.findBySheetIdAndGradeAndFromDate(sheetId, grade, from))
722	                    .orElseGet(() -> new Rate(sheetId, grade, pct, from));
