725	            Rate saved = rates.saveAndFlush(rate);
726	            audit.recordOnCommit("RATE_SET sheet=" + sheetId + " by=" + user + " grade=" + grade
727	                    + " rate=" + saved.getPct().setScale(2).toPlainString()
728	                    + (from != null ? " from=" + from : "")
729	                    + (to != null ? " to=" + to : ""));
730	            return saved;
731	        });
732	    }
